namespace DBench86\Benchmark{

use DBench86\Workload\Workload;
use PDO;
use Time\Duration;

/**
 * Orchestrates the execution of multiple workloads with consistent timing and metrics.
 *
 * Primary responsibility:
 * - Execute each workload in the benchmark suite using WorkloadTimer
 * - Track execution metrics across all runs
 * - Apply Partial Function Application (PFA) to specialize the measurement function
 *   for a given database connection and timer, reducing boilerplate when iterating
 *   over multiple workloads
 *
 * Design Rationale for PFA:
 * When running multiple workloads against the same database driver, the WorkloadTimer
 * and PDO connection remain constant across iterations. Using PFA, we specialize
 * the measurement function once, then iterate over workloads without repeating the
 * timer/connection arguments.
 *
 * Before PFA (PHP 8.5 style - using explicit closure):
 *   $measurements = [];
 *   foreach ($workloads as $workload) {
 *       $measurements[] = $timer->run($workload, $pdo);
 *   }
 *
 * With PFA (PHP 8.6 style - using native placeholder):
 *   $runOnThisDriver = $this->runMeasuredWorkload($timer, ?, $pdo);
 *   foreach ($workloads as $workload) {
 *       $measurements[] = $runOnThisDriver($workload);
 *   }
 *
 * The PFA approach is cleaner because:
 * 1. The partial function signature clearly shows what varies ($workload) vs. what's fixed
 * 2. No manual closure boilerplate needed
 * 3. Type safety is preserved at specialization time
 *
 * @see WorkloadTimer For the actual timing measurement logic
 * @see EXECUTION_METRICS For global metrics tracking
 */
final class WorkloadExecutor
{
    /**
     * @param Duration $timeout Timeout duration for each workload execution.
     */
    public function __construct(
        private readonly Duration $timeout,
    ) {}

    /**
     * Execute a collection of workloads against a specific database connection.
     *
     * Uses Partial Function Application to specialize the measurement function
     * for the given timer and PDO connection, creating a specialized function
     * that accepts only a Workload parameter.
     *
     * @param array<Workload> $workloads List of workloads to execute.
     * @param PDO $pdo Database connection for the workloads.
     *
     * @return array<string, WorkloadMeasurement> Map of workload name -> measurement result.
     */
    public function execute(array $workloads, PDO $pdo): array
    {
        $timer = new WorkloadTimer($this->timeout);

        // PHP 8.6 Partial Function Application:
        // Specialize runMeasuredWorkload() by fixing the timer and pdo,
        // leaving the workload parameter free. The resulting partial function
        // accepts only a Workload and returns a WorkloadMeasurement.
        //
        // Equivalent PHP 8.5 implementation (explicit closure):
        //   $runOnThisDriver = function(Workload $workload): WorkloadMeasurement {
        //       return $timer->run($workload, $pdo);
        //   };
        //
        // With PFA, the function signature is declarative and type-checked at
        // specialization time, not hidden inside a closure body.
        $runOnThisDriver = $this->runMeasuredWorkload($timer, ?, $pdo);

        $measurements = [];
        foreach ($workloads as $workload) {
            // Call the specialized function with the workload
            // The timer and pdo are already bound from the PFA
            $measurement = $runOnThisDriver($workload);
            $measurements[$workload->name()] = $measurement;
        }

        return $measurements;
    }

    /**
     * Generic workload measurement function to be specialized via PFA.
     *
     * This function is designed to be partially applied: the timer and pdo
     * are fixed, leaving the workload as the free parameter.
     *
     * In PHP 8.6, the placeholder syntax $this->runMeasuredWorkload($timer, ?, $pdo)
     * creates a Closure that binds $timer and $pdo, with the ? position accepting
     * a Workload when the partial is called.
     *
     * @param WorkloadTimer $timer The timer to use for measurement.
     * @param Workload $workload The workload to execute and measure.
     * @param PDO $pdo The database connection.
     *
     * @return WorkloadMeasurement The execution measurement result.
     */
    private function runMeasuredWorkload(
        WorkloadTimer $timer,
        Workload $workload,
        PDO $pdo,
    ): WorkloadMeasurement {
        return $timer->run($workload, $pdo);
    }
}
}

// Source: src/Benchmark/WorkloadMeasurement.php
namespace DBench86\Benchmark{

/**
 * Encapsulates timing and outcome metrics for a single workload execution.
 *
 * Stores:
 * - Elapsed time in nanoseconds (from hrtime(true))
 * - Number of rows affected by the workload
 * - Whether the workload timed out
 * - Whether the workload failed (threw an exception)
 *
 * This data is used by WorkloadExecutor to aggregate performance statistics
 * and identify problematic workloads that exceed timeout thresholds or throw exceptions.
 */
final class WorkloadMeasurement
{
    /**
     * @param int $durationNanoseconds Elapsed wall time in nanoseconds (hrtime(true) based).
     *                                  Not affected by system clock adjustments.
     * @param int $rowsAffected Number of rows affected by the workload execution.
     *                           Zero if execute() threw; completed executions retain their returned
     *                           logical operation count even when marked timed out.
     * @param bool $timedOut True if execution exceeded the configured timeout.
     * @param bool $failed True if the workload threw an exception during execute().
     */
    public function __construct(
        public readonly int $durationNanoseconds,
        public readonly int $rowsAffected,
        public readonly bool $timedOut = false,
        public readonly bool $failed = false,
    ) {}

    /**
     * Get elapsed duration as seconds (floating point).
     *
     * Useful for human-readable reporting and simple averaging.
     * Nanoseconds are divided by 1,000,000,000 to convert to seconds.
     *
     * Example:
     *   $elapsed = 1_500_000_000 nanoseconds
     *   $seconds = 1.5 seconds
     */
    public function durationSeconds(): float
    {
        return $this->durationNanoseconds / 1_000_000_000;
    }

    /**
     * Get elapsed duration as milliseconds (floating point).
     *
     * Useful for sub-second precision reporting.
     * Nanoseconds are divided by 1,000,000 to convert to milliseconds.
     *
     * Example:
     *   $elapsed = 1_500_000_000 nanoseconds
     *   $milliseconds = 1500.0 ms
     */
    public function durationMilliseconds(): float
    {
        return $this->durationNanoseconds / 1_000_000;
    }

    /**
     * Get throughput: rows affected per second.
     *
     * Returns 0 if duration is zero (prevents division by zero).
     * Useful for comparative performance analysis.
     *
     * Example:
     *   $elapsed = 1.0 second
     *   $rows = 1000
     *   $throughput = 1000.0 rows/sec
     */
    public function rowsPerSecond(): float
    {
        if ($this->durationNanoseconds === 0) {
            return 0.0;
        }
        return $this->rowsAffected / $this->durationSeconds();
    }
}
}

// Source: src/Benchmark/WorkloadResult.php
namespace DBench86\Benchmark{

use DBench86\Statistics\Statistics;

/** Untimed accounting for one workload; latency samples contain measured successes only. */
final class WorkloadResult
{
    public int $performed = 0;
    public int $successful = 0;
    public int $failed = 0;
    public int $timedOut = 0;
    public int $warmupPerformed = 0;
    public int $warmupFailed = 0;
    public int $warmupTimedOut = 0;
    public array $durations = [];
    public array $errors = [];

    public function __construct(public readonly int $requested) {}

    public function record(WorkloadMeasurement $measurement, bool $warmup = false): void
    {
        if ($warmup) {
            $this->warmupPerformed++;
            if ($measurement->failed) {
                $this->warmupFailed++;
            } elseif ($measurement->timedOut) {
                $this->warmupTimedOut++;
            }
            return;
        }

        $this->performed++;
        // A thrown execution is a failure even if a synthetic measurement has both flags.
        if ($measurement->failed) {
            $this->failed++;
        } elseif ($measurement->timedOut) {
            $this->timedOut++;
        } else {
            $this->successful++;
            $this->durations[] = $measurement->durationMilliseconds();
        }
    }

    /** No latency statistic is defined when there are no successful measured samples. */
    public function statistics(): ?array
    {
        if ($this->durations === []) {
            return null;
        }
        return [
            'min' => Statistics::minimum($this->durations),
            'median' => Statistics::median($this->durations),
            'p95' => Statistics::p95($this->durations),
            'max' => Statistics::maximum($this->durations),
        ];
    }

    public function hasFailures(): bool
    {
        return $this->performed !== $this->requested || $this->failed > 0
            || $this->timedOut > 0 || $this->warmupFailed > 0
            || $this->warmupTimedOut > 0 || $this->errors !== [];
    }
}
}

// Source: src/Benchmark/WorkloadTimer.php
namespace DBench86\Benchmark{

use DBench86\Workload\Workload;
use PDO;
use Time\Duration;

/**
 * High-resolution workload timing engine with timeout support.
 *
 * Measures workload execution time using monotonic timers (hrtime(true)) to avoid
 * being affected by system clock adjustments. Implements timeout checking using
 * PHP 8.6's native Time\Duration class for robust duration handling.
 *
 * Design principle: Measure ONLY the Workload::execute() call, exclude prepare()
 * and cleanup() from timing measurements. These operations are one-time setup/teardown,
 * not representative of benchmark workload performance.
 *
 * Timeout handling: If execution exceeds the timeout duration, mark the measurement
 * as timed out and increment EXECUTION_METRICS->timeouts. Do NOT throw exceptions,
 * which would interrupt the entire benchmark.
 *
 * Limitation (documented): PHP does not support interrupting a running PDO query
 * from within the same process. Timeout detection is therefore a posteriori
 * (after execution completes), not a priori (during execution). A workload that
 * takes 10 minutes will still complete even if timeout is 1 second.
 *
 * @see Workload interface contract (Phase E1)
 * @see EXECUTION_METRICS constant (Phase E1)
 * @see Time\Duration native PHP 8.6 feature
 */
final class WorkloadTimer
{
    /**
     * @param Duration $timeout Maximum allowed execution duration per workload.
     *                           Measured from start of Workload::execute() to end.
     *                           If exceeded, measurement is marked as timed out
     *                           and no exception is raised.
     */
    public function __construct(
        private readonly Duration $timeout,
    ) {}

    /**
     * Execute a workload with timing and timeout checking.
     *
     * IMPORTANT: This method ONLY times the Workload::execute() call.
     * Workload::prepare() and cleanup() are called by the orchestrator (Application.php),
     * NOT by this timer. This ensures:
     * - prepare() is called exactly once per workload (not per execution)
     * - cleanup() is called exactly once per workload (not per execution)
     * - executionCount accurately tracks total executions across all runs
     *
     * Workflow:
     * 1. Start high-resolution monotonic timer
     * 2. Call Workload::execute($pdo) with exception handling
     *    - If execute() throws: catch it, increment failures, continue benchmark
     *    - If execute() succeeds: capture return value (rows affected)
     * 3. Stop timer
     * 4. Check if elapsed time exceeds timeout
     * 5. Update metrics:
     *    - EXECUTION_METRICS->queries += 1 (one execution attempt, regardless of outcome)
     *    - If successful AND not timed out: EXECUTION_METRICS->runsCompleted += 1
     *    - If exception thrown: EXECUTION_METRICS->failures += 1
     *    - If timed out: EXECUTION_METRICS->timeouts += 1
     * 6. Return WorkloadMeasurement with elapsed time, rows affected, timeout flag, failure flag
     *
     * Semantic guarantee:
     * - queries = total execution attempts (always incremented, success or failure)
     * - runsCompleted = successful executions (queries - failures - timeouts, typically)
     * - failures = execution exceptions not caught at higher level
     * - timeouts = runs exceeding timeout threshold
     *
     * @param Workload $workload The workload to execute and measure.
     * @param PDO $pdo Database connection for the workload.
     *
     * @return WorkloadMeasurement Result containing duration, rows affected, timeout flag, failed flag.
     */
    public function run(Workload $workload, PDO $pdo): WorkloadMeasurement
    {
        // Phase 1: Start monotonic timer (nanosecond precision)
        // hrtime(true) is monotonic and not affected by system clock adjustments
        // NOTE: prepare() is NOT called here; it's called by the orchestrator (Application.php)
        // This ensures prepare() is called exactly once per workload, not per execution
        $startTime = hrtime(true);

        // Phase 2: Execute workload (STRICTLY TIMED) with exception handling
        // The execute() method returns the number of logical operations performed.
        // If it throws an exception, we catch it to prevent interrupting the benchmark.
        $rowsAffected = 0;
        $executionFailed = false;
        $executionException = null;

        try {
            $rowsAffected = $workload->execute($pdo);
        } catch (\Throwable $e) {
            $executionFailed = true;
            $executionException = $e;
        }

        // Phase 3: Stop monotonic timer
        $endTime = hrtime(true);
        $elapsedNanoseconds = $endTime - $startTime;

        // Phase 4: Check for timeout (a posteriori)
        // Convert elapsed nanoseconds to Duration for proper comparison.
        // Use Duration::compare() for explicit, documented comparison rather than
        // relying on operator overloading (which works, but compare() is the standard API).
        $elapsedDuration = Duration::fromNanoseconds($elapsedNanoseconds);
        $isTimeout = !$executionFailed &&
                     Duration::compare($elapsedDuration, $this->timeout) > 0;

        // Phase 5: Update metrics
        // These are fast O(1) operations that happen AFTER timing
        // NOTE: cleanup() is NOT called here; it's called by the orchestrator (Application.php)
        // This ensures cleanup() is called exactly once per workload, not per execution
        EXECUTION_METRICS->queries += 1; // One workload execution attempt

        // Only count as completed if no failure and no timeout
        if (!$executionFailed && !$isTimeout) {
            EXECUTION_METRICS->runsCompleted += 1;
        }

        // Increment failure counter if exception occurred
        if ($executionFailed) {
            EXECUTION_METRICS->failures += 1;
        }

        // Increment timeout counter if execution exceeded timeout
        if ($isTimeout) {
            EXECUTION_METRICS->timeouts += 1;
        }

        // Phase 6: Return measurement result
        return new WorkloadMeasurement(
            durationNanoseconds: $elapsedNanoseconds,
            rowsAffected: $rowsAffected,
            timedOut: $isTimeout,
            failed: $executionFailed,
        );
    }
}
}

// Source: src/Build/MonolithBuilder.php
namespace DBench86\Build{

/** Core-only packaging of the canonical classes, with inheritance dependencies first. */
final class MonolithBuilder
{
    public function __construct(private readonly string $projectDirectory) {}

    /** @return list<string> Project-relative source paths in deterministic build order. */
    public function sourceFiles(): array
    {
        $files = [];
        $directory = $this->projectDirectory . '/src';
        if (!is_dir($directory)) {
            throw new \RuntimeException('Building requires the canonical DBench86 src/ tree.');
        }
        foreach (new \RecursiveIteratorIterator(new \RecursiveDirectoryIterator($directory)) as $file) {
            if ($file->isFile() && $file->getExtension() === 'php') {
                $relative = substr($file->getPathname(), strlen($this->projectDirectory) + 1);
                $class = 'DBench86\\' . str_replace('/', '\\', substr($relative, 4, -4));
                $files[$class] = $relative;
            }
        }
        asort($files, SORT_STRING);
        $ordered = [];
        $visiting = [];
        $visit = function (string $class) use (&$visit, &$ordered, &$visiting, $files): void {
            if (isset($ordered[$class])) { return; }
            if (isset($visiting[$class])) {
                throw new \RuntimeException('Cyclic source dependency: ' . $class);
            }
            $visiting[$class] = true;
            // Reflection uses the normal production autoloader, never a second class parser.
            $reflection = new \ReflectionClass($class);
            if (realpath($reflection->getFileName()) !== realpath($this->projectDirectory . '/' . $files[$class])) {
                throw new \RuntimeException('Loaded class is not from the canonical source: ' . $class);
            }
            $dependencies = $reflection->getInterfaceNames();
            if ($parent = $reflection->getParentClass()) {
                $dependencies[] = $parent->getName();
            }
            sort($dependencies, SORT_STRING);
            foreach ($dependencies as $dependency) {
                if (isset($files[$dependency])) { $visit($dependency); }
            }
            unset($visiting[$class]);
            $ordered[$class] = $files[$class];
        };
        foreach (array_keys($files) as $class) { $visit($class); }
        return array_values($ordered);
    }

    public function build(): string
    {
        $output = "<?php\ndeclare(strict_types=1);\n\n"
            . "// Generated by DBench86 from canonical multi-file sources.\n"
            . "// Do not edit this file directly.\n";
        foreach ($this->sourceFiles() as $relative) {
            $output .= "\n// Source: {$relative}\n" . $this->namespaceBlock(file_get_contents($this->projectDirectory . '/' . $relative));
        }
        // Environment and CLI dispatch are the same production components as the launcher.
        $output .= <<<'PHP_SOURCE'

namespace {
    \DBench86\Configuration\Environment::load(__DIR__);
    exit(\DBench86\Cli\Launcher::run($argv, __DIR__));
}
PHP_SOURCE;
        return $output . "\n";
    }

    public function write(string $path): void
    {
        $source = $this->build();
        $directory = dirname($path);
        if (!is_dir($directory) && !mkdir($directory, 0777, true) && !is_dir($directory)) {
            throw new \RuntimeException('Cannot create build output directory.');
        }
        if (file_put_contents($path, $source) !== strlen($source)) {
            throw new \RuntimeException('Cannot write monolithic build.');
        }
    }

    /** Preserve all implementation tokens; only normalize the file-level envelope. */
    private function namespaceBlock(string $source): string
    {
        $tokens = \PhpToken::tokenize($source);
        $output = '';
        $namespaces = 0;
        for ($i = 0; $i < count($tokens); $i++) {
            $token = $tokens[$i];
            if ($token->is(T_OPEN_TAG)) { continue; }
            if ($token->is(T_DECLARE)) {
                $declaration = '';
                do { $declaration .= $tokens[$i]->text; } while ($tokens[$i++]->text !== ';');
                $i--;
                if (preg_replace('/\s+/', '', $declaration) !== 'declare(strict_types=1);') {
                    throw new \RuntimeException('Unsupported source declaration.');
                }
                continue;
            }
            if ($token->is(T_NAMESPACE)) {
                if (++$namespaces !== 1) { throw new \RuntimeException('Expected one namespace per source file.'); }
                do {
                    $output .= $tokens[$i]->text === ';' ? '{' : $tokens[$i]->text;
                } while ($tokens[$i++]->text !== ';');
                $i--;
                continue;
            }
            if ($token->is([T_CLOSE_TAG, T_INLINE_HTML, T_REQUIRE, T_REQUIRE_ONCE, T_INCLUDE, T_INCLUDE_ONCE, T_DIR, T_FILE])) {
                throw new \RuntimeException('Source requires explicit packaging support for: ' . $token->text);
            }
            $output .= $token->text;
        }
        if ($namespaces !== 1) { throw new \RuntimeException('Expected a namespaced production source.'); }
        return trim($output) . "\n}\n";
    }
}
}

// Source: src/Cli/ArgumentParser.php
namespace DBench86\Cli{

class ArgumentParser
{
    private const DEFAULT_DATABASE = 'all';
    private const DEFAULT_ROWS = 100_000;
    private const DEFAULT_RUNS = 30;
    private const DEFAULT_WARMUP = 5;
    private const DEFAULT_BATCH_SIZE = 100;
    private const DEFAULT_TIMEOUT = 30;
    private const DEFAULT_SORT = 'median';
    private const DEFAULT_DIRECTION = 'asc';

    public function parse(array $argv): array
    {
        $parsed = [
            'command' => null,
            'database' => self::DEFAULT_DATABASE,
            'rows' => self::DEFAULT_ROWS,
            'runs' => self::DEFAULT_RUNS,
            'warmup' => self::DEFAULT_WARMUP,
            'batch_size' => self::DEFAULT_BATCH_SIZE,
            'timeout' => self::DEFAULT_TIMEOUT,
            'sort' => self::DEFAULT_SORT,
            'direction' => self::DEFAULT_DIRECTION,
            'debug' => false,
            'help' => false,
        ];

        // Skip program name
        for ($i = 1; $i < count($argv); $i++) {
            $arg = $argv[$i];

            if ($arg === '--help' || $arg === '-h') {
                $parsed['help'] = true;
                continue;
            }

            if ($arg === '--debug') {
                $parsed['debug'] = true;
                continue;
            }

            if (strpos($arg, '--') === 0) {
                if (strpos($arg, '=') === false) {
                    throw new \InvalidArgumentException("Option sans valeur : {$arg}");
                }

                [$name, $value] = explode('=', $arg, 2);
                $name = substr($name, 2);

                if ($name === '') {
                    throw new \InvalidArgumentException("Option invalide : {$arg}");
                }

                $keyName = strtr($name, '-', '_');

                if (!in_array($keyName, ['database', 'rows', 'runs', 'warmup', 'batch_size', 'timeout', 'sort', 'direction'], true)) {
                    throw new \InvalidArgumentException("Option inconnue : --{$name}");
                }

                $parsed[$keyName] = $value;
            } else {
                // Positional argument (command)
                if ($parsed['command'] !== null || $arg !== 'run') {
                    throw new \InvalidArgumentException("Commande inconnue : {$arg}");
                }
                $parsed['command'] = $arg;
            }
        }

        return $parsed;
    }
}
}

// Source: src/Cli/CommandDefinition.php
namespace DBench86\Cli{

class CommandDefinition
{
    /**
     * Define 'run' command parameters with inline documentation via Parameter DocComments.
     * This is the single source of truth for command parameters.
     */
    public static function runCommand(
        /** Moteur(s) de base de données à benchmarker : all, mariadb, postgresql, sqlite */
        string $database = 'all',

        /** Nombre de lignes générées dans le jeu de données */
        int $rows = 100_000,

        /** Nombre d'itérations mesurées */
        int $runs = 30,

        /** Nombre d'itérations de préchauffage avant mesure */
        int $warmup = 5,

        /** Taille des lots d'insertion */
        int $batch_size = 100,

        /** Timeout maximal par test en secondes entières (> 0) ; fractions rejetées, 0 interdit */
        int $timeout = 30,

        /** Métrique de tri des latences réussies : min, median, p95, max */
        string $sort = 'median',

        /** Direction de tri : asc ou desc */
        string $direction = 'asc',

        /** Mode débogage (affiche les détails complets en cas d'erreur) */
        bool $debug = false,
    ): void {}

    /**
     * Extract parameter documentation from runCommand() method using Reflection.
     * Returns an array of parameter names and their docstrings.
     */
    public static function getParameterDocumentation(): array
    {
        $reflection = new \ReflectionMethod(self::class, 'runCommand');
        $parameters = $reflection->getParameters();
        $documentation = [];

        foreach ($parameters as $param) {
            $docComment = $param->getDocComment();
            if ($docComment !== null) {
                // Extract the text from /** ... */
                $docComment = trim($docComment);
                $docComment = preg_replace('/^\/\*\*\s*/', '', $docComment);
                $docComment = preg_replace('/\s*\*\/$/', '', $docComment);
                $docComment = preg_replace('/^\s*\*\s*/m', '', $docComment);
                $docComment = trim($docComment);

                $documentation[$param->name] = [
                    'name' => $param->name,
                    'docstring' => $docComment,
                    'default' => $param->getDefaultValue(),
                ];
            }
        }

        return $documentation;
    }

    /**
     * Generate help text from parameter documentation.
     */
    public static function getHelpText(): string
    {
        $docs = self::getParameterDocumentation();
        $help = "Usage: dbench86.php run [OPTIONS]\n\n";
        $help .= "Build: dbench86.php --build-monolith (requires canonical sources)\n\n";
        $help .= "Options:\n  --help, -h            Afficher cette aide\n";

        foreach ($docs as $param) {
            $name = str_replace('_', '-', $param['name']);
            $default = $param['default'] ?? 'null';

            if (is_string($default)) {
                $default = "'{$default}'";
            } elseif (is_int($default)) {
                $default = (string)$default;
            } elseif (is_bool($default)) {
                $default = $default ? 'true' : 'false';
            } elseif ($default === null) {
                $default = 'null';
            }

            $help .= sprintf(
                "  --%-20s  %s (default: %s)\n",
                $name,
                $param['docstring'],
                $default
            );
        }

        return $help;
    }
}
}

// Source: src/Cli/Launcher.php
namespace DBench86\Cli{

use DBench86\Application;
use DBench86\Build\MonolithBuilder;

/** Separate build dispatch from benchmark argument parsing and execution. */
final class Launcher
{
    public static function run(array $argv, string $projectDirectory): int
    {
        if (in_array('--build-monolith', array_slice($argv, 1), true)) {
            if (count($argv) !== 2) {
                fwrite(STDERR, "Error: --build-monolith must be used alone.\n");
                return 1;
            }
            try {
                (new MonolithBuilder($projectDirectory))->write($projectDirectory . '/dist/dbench86-monolith.php');
                echo "Built dist/dbench86-monolith.php\n";
                return 0;
            } catch (\Throwable $error) {
                fwrite(STDERR, 'Build error: ' . $error->getMessage() . "\n");
                return 1;
            }
        }
        return (new Application())->run($argv);
    }
}
}

// Source: src/Configuration/BenchmarkConfiguration.php
namespace DBench86\Configuration{

use SortDirection;
use InvalidArgumentException;

class BenchmarkConfiguration
{
    public readonly string $database;
    public readonly int $rows;
    public readonly int $runs;
    public readonly int $warmup;
    public readonly int $batchSize;
    public readonly int $timeout;
    public readonly string $sort;
    public readonly SortDirection $direction;
    public readonly bool $debug;

    public function __construct(array $parsed)
    {
        $this->database = $this->validateDatabase($parsed['database']);
        $this->rows = $this->validatePositiveInt($parsed['rows'], 'rows');
        $this->runs = $this->validatePositiveInt($parsed['runs'], 'runs');
        $this->warmup = $this->validateNonNegativeInt($parsed['warmup'], 'warmup');
        if ($this->warmup > PHP_INT_MAX - $this->runs) {
            throw new InvalidArgumentException('Combined warmup + runs exceeds the supported integer execution count');
        }
        $this->batchSize = $this->validatePositiveInt($parsed['batch_size'], 'batch-size');
        $this->timeout = $this->validateTimeout($parsed['timeout']);
        $this->sort = $this->validateSort($parsed['sort']);
        $this->direction = $this->validateDirection($parsed['direction']);
        $this->debug = $parsed['debug'];
    }

    private function validateDatabase(string $value): string
    {
        $allowed = ['all', 'mariadb', 'postgresql', 'sqlite'];
        if (!in_array($value, $allowed, true)) {
            throw new InvalidArgumentException(
                "Valeur invalide pour --database : {$value}. Valeurs acceptées : " . implode(', ', $allowed)
            );
        }
        return $value;
    }

    private function validateTimeout(mixed $value): int
    {
        $raw = trim((string) $value);
        if ((!is_int($value) && !is_string($value)) || preg_match('/\A[0-9]+\z/', $raw) !== 1) {
            throw new InvalidArgumentException(
                "--timeout doit être un nombre entier de secondes, valeur reçue : '{$raw}'"
            );
        }

        // Check the range as text before casting, so oversized integers cannot be saturated.
        $digits = ltrim($raw, '0');
        $maximum = (string) PHP_INT_MAX;
        if (strlen($digits) > strlen($maximum)
            || (strlen($digits) === strlen($maximum) && strcmp($digits, $maximum) > 0)) {
            throw new InvalidArgumentException(
                "--timeout dépasse le nombre maximal de secondes ({$maximum}), valeur reçue : '{$raw}'"
            );
        }

        return $this->validatePositiveInt($raw, 'timeout');
    }

    private function validateDecimalInt(mixed $value, string $name): int
    {
        if ((!is_int($value) && !is_string($value))
            || preg_match('/\A[0-9]+\z/', (string) $value) !== 1) {
            throw new InvalidArgumentException("--{$name} must be a whole decimal integer");
        }
        $digits = ltrim((string) $value, '0');
        $maximum = (string) PHP_INT_MAX;
        if (strlen($digits) > strlen($maximum)
            || (strlen($digits) === strlen($maximum) && strcmp($digits, $maximum) > 0)) {
            throw new InvalidArgumentException("--{$name} exceeds PHP_INT_MAX");
        }
        return (int) $value;
    }

    private function validatePositiveInt(mixed $value, string $name): int
    {
        $int = $this->validateDecimalInt($value, $name);
        if ($int <= 0) {
            throw new InvalidArgumentException("--{$name} doit être positif (> 0), reçu : {$value}");
        }
        return $int;
    }

    private function validateNonNegativeInt(mixed $value, string $name): int
    {
        return $this->validateDecimalInt($value, $name);
    }

    private function validateSort(string $value): string
    {
        if (!in_array($value, ['min', 'median', 'p95', 'max'], true)) {
            throw new InvalidArgumentException("Valeur invalide pour --sort : {$value}. Valeurs acceptées : min, median, p95, max");
        }
        return $value;
    }

    private function validateDirection(string $value): SortDirection
    {
        return match ($value) {
            'asc' => SortDirection::Ascending,
            'desc' => SortDirection::Descending,
            default => throw new InvalidArgumentException(
                "Valeur invalide pour --direction : {$value}. Valeurs acceptées : asc, desc"
            ),
        };
    }
}
}

// Source: src/Configuration/Environment.php
namespace DBench86\Configuration{

/** Load optional runtime configuration; its contents are never build inputs. */
final class Environment
{
    public static function load(string $directory): void
    {
        // Load environment variables from .env file
        $envFile = $directory . '/.env';
        if (file_exists($envFile)) {
            $lines = file($envFile, FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES);
            foreach ($lines as $line) {
                // Skip comments
                if (strpos(trim($line), '#') === 0) {
                    continue;
                }

                // Parse KEY=VALUE
                if (strpos($line, '=') !== false) {
                    [$key, $value] = explode('=', $line, 2);
                    $key = trim($key);
                    $value = trim($value);

                    // Only set if not already set in environment
                    if (!getenv($key)) {
                        putenv("{$key}={$value}");
                        $_ENV[$key] = $value;
                    }
                }
            }
        }
    }
}
}

// Source: src/Dataset/DatasetGenerator.php
namespace DBench86\Dataset{

/**
 * Generates deterministic test dataset using a DeterministicGenerator and logical Schema.
 *
 * Produces rows for all four tables (users, products, orders, order_items) with
 * guaranteed reproducibility: same seed + same row count → identical data sequences.
 *
 * Uses PHP generators (yield) to minimize memory footprint even at large scale
 * (--rows=1000000), avoiding the need to buffer entire tables in memory.
 *
 * Referential integrity is maintained:
 *   • Every order.user_id references a user generated by generateUsers()
 *   • Every order_item.order_id references an order generated by generateOrders()
 *   • Every order_item.product_id references a product generated by generateProducts()
 *
 * Cardinality:
 *   • Users: $requestedRows (primary scale factor)
 *   • Products: 15% of $requestedRows (shared catalog)
 *   • Orders: 30% of $requestedRows (multiple per user)
 *   • Order Items: 1-5 per order (variable, realistic)
 */
final class DatasetGenerator
{
    /**
     * Percentage of requested rows used for product catalog.
     * Typical benchmark: smaller product catalog than user base.
     */
    private const float PRODUCT_SCALE_FACTOR = 0.15;

    /**
     * Percentage of requested rows used for orders.
     * Typical benchmark: multiple orders per user.
     */
    private const float ORDER_SCALE_FACTOR = 0.30;

    /**
     * Range of order items per order (inclusive).
     */
    private const int MIN_ITEMS_PER_ORDER = 1;
    private const int MAX_ITEMS_PER_ORDER = 5;

    public function __construct(
        private readonly DeterministicGenerator $generator,
        private readonly int $requestedRows,
    )
    {
        if ($requestedRows <= 0) {
            throw new \InvalidArgumentException('requestedRows must be positive');
        }
    }

    /**
     * Generate user records.
     *
     * Yields rows with: id, email (unique), name, created_at.
     * Total count: $requestedRows
     *
     * @return iterable<int, array{id: int, email: string, name: string, created_at: string}>
     */
    public function generateUsers(): iterable
    {
        for ($id = 1; $id <= $this->requestedRows; $id++) {
            yield $id => [
                'id' => $id,
                'email' => 'user' . str_pad((string)$id, 8, '0', STR_PAD_LEFT) . '@' . $this->generator->nextString(8) . '.test',
                'name' => $this->generateFullName(),
                'created_at' => $this->generateTimestamp(),
            ];
        }
    }

    /**
     * Generate product records.
     *
     * Yields rows with: id, sku (unique), name, price.
     * Total count: ~15% of $requestedRows
     *
     * Price is rounded to 2 decimals for cross-engine consistency (DECIMAL/NUMERIC compatibility).
     *
     * @return iterable<int, array{id: int, sku: string, name: string, price: float}>
     */
    public function generateProducts(): iterable
    {
        $productCount = max(1, (int)($this->requestedRows * self::PRODUCT_SCALE_FACTOR));

        for ($id = 1; $id <= $productCount; $id++) {
            // Generate price and round to 2 decimals for consistency across all engines
            $price = $this->generator->nextFloat(10.0, 9999.99);
            $priceTruncated = round($price, 2);

            yield $id => [
                'id' => $id,
                'sku' => 'SKU-' . str_pad((string)$id, 8, '0', STR_PAD_LEFT),
                'name' => $this->generateProductName(),
                'price' => $priceTruncated,
            ];
        }
    }

    /**
     * Generate order records, referencing users.
     *
     * Yields rows with: id, user_id (foreign key), status, created_at.
     * Total count: ~30% of $requestedRows
     * Integrity: all user_ids reference generated users.
     *
     * @param array<int>|int $userIds Valid IDs, or count of contiguous IDs 1..N (bounded memory)
     * @return iterable<int, array{id: int, user_id: int, status: string, created_at: string}>
     */
    public function generateOrders(array|int $userIds): iterable
    {
        if (is_int($userIds) ? $userIds <= 0 : empty($userIds)) {
            throw new \InvalidArgumentException('userIds must not be empty');
        }

        $orderCount = max(1, (int)($this->requestedRows * self::ORDER_SCALE_FACTOR));
        $statuses = ['pending', 'completed', 'cancelled'];

        for ($id = 1; $id <= $orderCount; $id++) {
            yield $id => [
                'id' => $id,
                'user_id' => is_int($userIds)
                    ? 1 + $this->generator->nextInt(0, $userIds - 1)
                    : $this->generator->nextChoice($userIds),
                'status' => $this->generator->nextChoice($statuses),
                'created_at' => $this->generateTimestamp(),
            ];
        }
    }

    /**
     * Generate order item records, referencing orders and products.
     *
     * Yields rows with: id, order_id (foreign key), product_id (foreign key), quantity, unit_price.
     * Cardinality: 1-5 items per order (variable, realistic).
     * Integrity: all order_ids and product_ids reference generated records.
     *
     * Unit price is rounded to 2 decimals for cross-engine consistency (DECIMAL/NUMERIC compatibility).
     *
     * @param array<int>|int $orderIds Valid IDs, or count of contiguous IDs 1..N
     * @param array<int>|int $productIds Valid IDs, or count of contiguous IDs 1..N
     * @return iterable<int, array{id: int, order_id: int, product_id: int, quantity: int, unit_price: float}>
     */
    public function generateOrderItems(array|int $orderIds, array|int $productIds): iterable
    {
        if (is_int($orderIds) ? $orderIds <= 0 : empty($orderIds)) {
            throw new \InvalidArgumentException('orderIds must not be empty');
        }
        if (is_int($productIds) ? $productIds <= 0 : empty($productIds)) {
            throw new \InvalidArgumentException('productIds must not be empty');
        }

        $itemId = 1;

        foreach (is_int($orderIds) ? $this->contiguousIds($orderIds) : $orderIds as $orderId) {
            // Variable number of items per order (1-5)
            $itemsInOrder = $this->generator->nextInt(self::MIN_ITEMS_PER_ORDER, self::MAX_ITEMS_PER_ORDER);

            for ($i = 0; $i < $itemsInOrder; $i++) {
                // Round unit_price to 2 decimals for consistency across all engines
                $unitPrice = $this->generator->nextFloat(5.0, 999.99);
                $unitPriceTruncated = round($unitPrice, 2);

                yield $itemId => [
                    'id' => $itemId,
                    'order_id' => $orderId,
                    'product_id' => is_int($productIds)
                        ? 1 + $this->generator->nextInt(0, $productIds - 1)
                        : $this->generator->nextChoice($productIds),
                    'quantity' => $this->generator->nextInt(1, 10),
                    'unit_price' => $unitPriceTruncated,
                ];
                $itemId++;
            }
        }
    }

    /**
     * Generate a realistic full name (FirstName LastName).
     */
    private function contiguousIds(int $count): iterable
    {
        for ($id = 1; $id <= $count; $id++) {
            yield $id;
        }
    }

    private function generateFullName(): string
    {
        $firstNames = ['John', 'Jane', 'Michael', 'Sarah', 'Robert', 'Emma', 'William', 'Sophia'];
        $lastNames = ['Smith', 'Johnson', 'Williams', 'Brown', 'Jones', 'Garcia', 'Miller', 'Davis'];

        $first = $this->generator->nextChoice($firstNames);
        $last = $this->generator->nextChoice($lastNames);

        return "{$first} {$last}";
    }

    /**
     * Generate a realistic product name.
     */
    private function generateProductName(): string
    {
        $adjectives = ['Professional', 'Standard', 'Premium', 'Economy', 'Deluxe'];
        $nouns = ['Widget', 'Tool', 'Device', 'Gadget', 'Component'];

        $adj = $this->generator->nextChoice($adjectives);
        $noun = $this->generator->nextChoice($nouns);

        return "{$adj} {$noun} v" . $this->generator->nextInt(1, 9);
    }

    /**
     * Generate an ISO 8601 timestamp string (deterministic, fixed reference point).
     *
     * Uses a fixed reference date (2022-01-01) to ensure cross-session reproducibility.
     * All timestamps are generated relative to this fixed point, not the current time.
     */
    private function generateTimestamp(): string
    {
        // Fixed reference: 2022-01-01 00:00:00 UTC
        $referenceTime = 1_641_024_000;

        // Generate timestamps within a 2-year window from the reference
        $twoYearsInSeconds = 365 * 2 * 86_400;
        $randomOffset = $this->generator->nextInt(0, $twoYearsInSeconds);
        $timestamp = $referenceTime + $randomOffset;

        return gmdate('Y-m-d H:i:s', $timestamp);
    }
}
}

// Source: src/Dataset/DatasetPopulator.php
namespace DBench86\Dataset{

use PDO;
use DBench86\Driver\DatabaseDriver;
use DBench86\Exception\BenchmarkPreparationException;

/**
 * Orchestrates the complete dataset population cycle.
 *
 * Workflow:
 * 1. Call createSchema() on the driver to establish the database structure
 * 2. Generate rows using DatasetGenerator (deterministic, based on seed)
 * 3. Insert rows via prepared statements, reused across all rows per table
 * 4. Verify row counts match requested scale
 *
 * This class does NOT use BatchLimitCalculator yet — that's a workload concern
 * (when executing query benchmarks with specific batch constraints). Here, we
 * simply populate the database line-by-line using reused prepared statements
 * for efficiency, without worrying about batch limits.
 *
 * Insertion follows schema dependencies (users → products → orders → order_items)
 * to respect foreign key constraints.
 */
final class DatasetPopulator
{
    /**
     * Construct a DatasetPopulator instance.
     *
     * @param DatabaseDriver $driver The database driver to use for all operations
     * @param DeterministicGenerator $generator The pseudo-random generator for data
     * @param int $requestedRows The number of user rows to generate (scales other tables)
     */
    public function __construct(
        private readonly DatabaseDriver $driver,
        private readonly DeterministicGenerator $generator,
        private readonly int $requestedRows,
    ) {
        if ($this->requestedRows <= 0) {
            throw new \InvalidArgumentException(
                'requestedRows must be strictly positive'
            );
        }
    }

    /**
     * Execute the complete population cycle.
     *
     * Flow:
     * 1. Connect to the database via $driver
     * 2. Call driver->createSchema() to establish tables
     * 3. Generate and insert rows for all 4 tables
     * 4. Verify row counts against expected values
     *
     * @return PDO The active database connection used for population
     * @throws BenchmarkPreparationException If any step fails
     */
    public function populate(): PDO
    {
        $pdo = $this->driver->connect();

        try {
            // Reset schema if it already exists (truncate tables, reset auto_increment)
            // This handles re-population scenarios gracefully
            try {
                $this->driver->resetSchema($pdo);
            } catch (\Exception $e) {
                // If resetSchema fails (e.g., no existing schema), that's ok
                // We'll create it fresh in the next step
            }

            // Create schema (tables, indexes, constraints)
            // If schema already exists after reset, this is a no-op
            $this->driver->createSchema($pdo);

            // Generate dataset
            $datasetGen = new DatasetGenerator($this->generator, $this->requestedRows);

            // Generate and insert data in dependency order
            $this->insertUsers($pdo, $datasetGen);
            $this->insertProducts($pdo, $datasetGen);
            $this->insertOrders($pdo, $datasetGen);
            $this->insertOrderItems($pdo, $datasetGen);

            // Verify row counts
            $this->verifyRowCounts($pdo);

            return $pdo;
        } catch (\Exception $e) {
            if (!($e instanceof BenchmarkPreparationException)) {
                throw new BenchmarkPreparationException(
                    'Dataset population failed: ' . $e->getMessage(),
                    0,
                    $e
                );
            }
            throw $e;
        }
    }

    /**
     * Stream users one row at a time.
     *
     * Uses a reusable prepared statement to insert each user row.
     *
     * @param PDO $pdo Active database connection
     * @param DatasetGenerator $datasetGen The generator for user data
     * @throws BenchmarkPreparationException If insertion fails
     */
    private function insertUsers(PDO $pdo, DatasetGenerator $datasetGen): void
    {
        try {
            $stmt = $pdo->prepare(
                'INSERT INTO users (email, name, created_at) VALUES (?, ?, ?)'
            );

            foreach ($datasetGen->generateUsers() as $user) {
                $stmt->execute([
                    $user['email'],
                    $user['name'],
                    $user['created_at'],
                ]);
            }
        } catch (\PDOException $e) {
            throw new BenchmarkPreparationException(
                'Failed to insert users: ' . $e->getMessage(),
                0,
                $e
            );
        }
    }

    /**
     * Stream products one row at a time.
     *
     * Uses a reusable prepared statement to insert each product row.
     *
     * @param PDO $pdo Active database connection
     * @param DatasetGenerator $datasetGen The generator for product data
     * @throws BenchmarkPreparationException If insertion fails
     */
    private function insertProducts(PDO $pdo, DatasetGenerator $datasetGen): void
    {
        try {
            $stmt = $pdo->prepare(
                'INSERT INTO products (sku, name, price) VALUES (?, ?, ?)'
            );

            foreach ($datasetGen->generateProducts() as $product) {
                $stmt->execute([
                    $product['sku'],
                    $product['name'],
                    (float)$product['price'],
                ]);
            }
        } catch (\PDOException $e) {
            throw new BenchmarkPreparationException(
                'Failed to insert products: ' . $e->getMessage(),
                0,
                $e
            );
        }
    }

    /**
     * Insert all orders.
     *
     * Uses a reusable prepared statement to insert each order row.
     * Requires user IDs from insertUsers() to satisfy foreign key constraints.
     *
     * @param PDO $pdo Active database connection
     * @param DatasetGenerator $datasetGen The generator for order data
     * @throws BenchmarkPreparationException If insertion fails
     */
    private function insertOrders(
        PDO $pdo,
        DatasetGenerator $datasetGen,
    ): void {
        try {
            // Reset schemas assign contiguous IDs 1..N. Counts replace O(N) ID lists.
            $userIds = (int)$pdo->query('SELECT COUNT(*) FROM users')->fetchColumn();
            if (empty($userIds)) {
                throw new BenchmarkPreparationException(
                    'No users found in database for order FK references'
                );
            }

            $stmt = $pdo->prepare(
                'INSERT INTO orders (user_id, status, created_at) VALUES (?, ?, ?)'
            );

            foreach ($datasetGen->generateOrders($userIds) as $order) {
                $stmt->execute([
                    (int)$order['user_id'],
                    $order['status'],
                    $order['created_at'],
                ]);
            }
        } catch (\PDOException $e) {
            throw new BenchmarkPreparationException(
                'Failed to insert orders: ' . $e->getMessage(),
                0,
                $e
            );
        }
    }

    /**
     * Insert all order_items.
     *
     * Uses a reusable prepared statement to insert each order_item row.
     * Requires order IDs and product IDs from the database to satisfy FK constraints.
     *
     * @param PDO $pdo Active database connection
     * @param DatasetGenerator $datasetGen The generator for order_item data
     * @throws BenchmarkPreparationException If insertion fails
     */
    private function insertOrderItems(
        PDO $pdo,
        DatasetGenerator $datasetGen,
    ): void {
        try {
            // Contiguous ID counts preserve the exact generator sequence without ID arrays.
            $orderIds = (int)$pdo->query('SELECT COUNT(*) FROM orders')->fetchColumn();
            $productIds = (int)$pdo->query('SELECT COUNT(*) FROM products')->fetchColumn();

            if (empty($orderIds)) {
                throw new BenchmarkPreparationException(
                    'No orders found in database for order_items FK references'
                );
            }
            if (empty($productIds)) {
                throw new BenchmarkPreparationException(
                    'No products found in database for order_items FK references'
                );
            }

            $stmt = $pdo->prepare(
                'INSERT INTO order_items (order_id, product_id, quantity, unit_price) VALUES (?, ?, ?, ?)'
            );

            foreach ($datasetGen->generateOrderItems($orderIds, $productIds) as $item) {
                $stmt->execute([
                    (int)$item['order_id'],
                    (int)$item['product_id'],
                    (int)$item['quantity'],
                    (float)$item['unit_price'],
                ]);
            }
        } catch (\PDOException $e) {
            throw new BenchmarkPreparationException(
                'Failed to insert order_items: ' . $e->getMessage(),
                0,
                $e
            );
        }
    }

    /**
     * Verify that row counts in all tables match expected values.
     *
     * Queries each table for actual row count and compares against expected
     * values based on the requested scale and cardinality factors.
     *
     * Expected row counts:
     * - users: exactly requestedRows
     * - products: ceil(requestedRows * PRODUCT_SCALE_FACTOR) ≈ 15% of users
     * - orders: ceil(requestedRows * ORDER_SCALE_FACTOR) ≈ 30% of users
     * - order_items: variable (1-5 per order, typically 3x orders)
     *
     * @param PDO $pdo Active database connection
     * @throws BenchmarkPreparationException If any count doesn't match expected
     */
    private function verifyRowCounts(PDO $pdo): void
    {
        try {
            $counts = [
                'users' => (int)$pdo->query('SELECT COUNT(*) FROM users')->fetchColumn(),
                'products' => (int)$pdo->query('SELECT COUNT(*) FROM products')->fetchColumn(),
                'orders' => (int)$pdo->query('SELECT COUNT(*) FROM orders')->fetchColumn(),
                'order_items' => (int)$pdo->query('SELECT COUNT(*) FROM order_items')->fetchColumn(),
            ];

            // Verify users count (must be exact)
            if ($counts['users'] !== $this->requestedRows) {
                throw new BenchmarkPreparationException(
                    sprintf(
                        'User count mismatch: expected %d, got %d',
                        $this->requestedRows,
                        $counts['users']
                    )
                );
            }

            // Verify products count (approximately 15% of users)
            $expectedProducts = max(1, (int)ceil($this->requestedRows * 0.15));
            $tolerance = max(1, (int)ceil($expectedProducts * 0.1)); // 10% tolerance
            if (abs($counts['products'] - $expectedProducts) > $tolerance) {
                throw new BenchmarkPreparationException(
                    sprintf(
                        'Product count unexpected: expected ~%d (±%d), got %d',
                        $expectedProducts,
                        $tolerance,
                        $counts['products']
                    )
                );
            }

            // Verify orders count (approximately 30% of users)
            $expectedOrders = max(1, (int)ceil($this->requestedRows * 0.30));
            $tolerance = max(1, (int)ceil($expectedOrders * 0.1));
            if (abs($counts['orders'] - $expectedOrders) > $tolerance) {
                throw new BenchmarkPreparationException(
                    sprintf(
                        'Order count unexpected: expected ~%d (±%d), got %d',
                        $expectedOrders,
                        $tolerance,
                        $counts['orders']
                    )
                );
            }

            // Verify order_items count (1-5 per order, typically ~3x orders)
            $minItems = $counts['orders'] * 1;
            $maxItems = $counts['orders'] * 5;
            if ($counts['order_items'] < $minItems || $counts['order_items'] > $maxItems) {
                throw new BenchmarkPreparationException(
                    sprintf(
                        'Order items count out of range: expected %d-%d (1-5 per order), got %d',
                        $minItems,
                        $maxItems,
                        $counts['order_items']
                    )
                );
            }
        } catch (\PDOException $e) {
            throw new BenchmarkPreparationException(
                'Failed to verify row counts: ' . $e->getMessage(),
                0,
                $e
            );
        }
    }
}
}

// Source: src/Dataset/DeterministicGenerator.php
namespace DBench86\Dataset{

/**
 * Deterministic pseudorandom number generator with guaranteed reproducibility
 * across PHP versions and platforms.
 *
 * Implements PCG32 (Permuted Congruential Generator, 32-bit variant):
 * a fast, simple, statistically excellent PRNG that does not rely on PHP's
 * built-in mt_rand() or random_int(), which are not guaranteed to be stable
 * across versions and platforms.
 *
 * Algorithm: PCG32 from http://www.pcg-random.org/
 * Paper: "PCG: A Family of Simple Fast Space-Efficient Statistically Good
 *        Algorithms for Random Number Generation"
 *        Melissa E. O'Neill, Harvey Mudd College
 *
 * Internal state (64-bit) is updated using a linear congruential generator:
 *   state = (state * 6364136223846793005) + 1442695040888963407
 *
 * Output is produced by applying a permutation to decorrelate output from state:
 *   1. Extract the "middle bits" via xorshift
 *   2. Apply a rotation amount derived from high bits
 *   3. Rotate to produce the final 32-bit value
 *
 * Properties:
 *   - Period: 2^64 (full state space)
 *   - Output: 32-bit unsigned integers
 *   - Passes statistical tests (PractRand, Crush suite)
 *   - Deterministic: same seed → same sequence
 *   - Reproducible: works identically on any PHP version
 *   - No external dependencies
 *
 * Usage:
 *   $gen = new DeterministicGenerator(12345);
 *   $int = $gen->nextInt(1, 100);
 *   $float = $gen->nextFloat(0.0, 1.0);
 *   $string = $gen->nextString(8);
 *   $choice = $gen->nextChoice(['apple', 'banana', 'cherry']);
 */
final class DeterministicGenerator
{
    /**
     * Internal 64-bit state, stored as two 32-bit unsigned integers.
     * PHP integers are platform-dependent (32 or 64 bit), so we decompose
     * the 64-bit state into two 32-bit parts to ensure cross-platform consistency.
     */
    private int $stateLow;   // Lower 32 bits
    private int $stateHigh;  // Upper 32 bits

    /**
     * PCG32 constants (verified against http://www.pcg-random.org/download.html).
     */
    private const int MULTIPLIER_LOW = 0x6C078965;    // Lower 32 bits of multiplier
    private const int MULTIPLIER_HIGH = 0x5D308E6D;   // Upper 32 bits of multiplier
    private const int INCREMENT_LOW = 0x88963407;     // Lower 32 bits of increment
    private const int INCREMENT_HIGH = 0x5555;        // Upper 32 bits of increment

    /**
     * Initialize the generator with a seed.
     *
     * The seed is expanded into the full 64-bit state to ensure good
     * distribution even for small seed values.
     *
     * @param int $seed Initial seed value (any integer)
     */
    public function __construct(int $seed)
    {
        // Expand seed to 64-bit state using a simple hash function
        // This ensures seeds like 0, 1, 2 produce different sequences
        $state = $seed;

        // Mix bits to ensure good distribution
        $state = ($state ^ 61) ^ ($state >> 16);
        $state = $state + ($state << 3);
        $state = $state ^ ($state >> 4);
        $state = $state * 0x27D4EB2D;
        $state = $state ^ ($state >> 15);

        // Extract low and high 32-bit parts
        $this->stateLow = $state & 0xFFFFFFFF;
        $this->stateHigh = ($state >> 32) & 0xFFFFFFFF;

        // Advance by one step to avoid initial state artifacts
        $this->advance();
    }

    /**
     * Advance the internal state one step using the LCG formula.
     *
     * state = state * multiplier + increment
     *
     * Uses Karatsuba-like decomposition to multiply two 64-bit values in 32-bit arithmetic,
     * handling PHP's platform-dependent integer size by forcing 32-bit operations.
     */
    private function advance(): void
    {
        // PCG32 multiplier: 6364136223846793005 = 0x5851F42D4C957F2D
        // PCG32 increment: 1442695040888963407 = 0x14057B7EF767814F

        // Decompose into 32-bit parts for cross-platform consistency
        $ml = 0x4C957F2D;  // Low 32 bits of multiplier
        $mh = 0x5851F42D;  // High 32 bits of multiplier
        $il = 0xF767814F;  // Low 32 bits of increment
        $ih = 0x14057B7E;  // High 32 bits of increment

        // Multiply state by multiplier using Karatsuba decomposition
        // (a_h * 2^32 + a_l) * (m_h * 2^32 + m_l) mod 2^64

        // Compute partial products and accumulate
        $p0 = $this->mulLo32($this->stateLow, $ml);     // Low part of low×low
        $p1 = $this->mulHi32($this->stateLow, $ml);     // High part of low×low  (carry to mid)
        $p2 = $this->mulLo32($this->stateLow, $mh);     // Low×high product (goes to mid)
        $p3 = $this->mulLo32($this->stateHigh, $ml);    // High×low product (goes to mid)

        // Accumulate into low 32 bits
        $this->stateLow = $p0 & 0xFFFFFFFF;

        // Accumulate carries into high 32 bits
        $carry = ($p0 >> 32) ? 1 : 0;
        $mid = ($p1 + $p2 + $p3 + $carry) & 0xFFFFFFFF;

        $this->stateHigh = $mid & 0xFFFFFFFF;

        // Add increment
        $this->stateLow = ($this->stateLow + $il) & 0xFFFFFFFF;
        $carry = (($this->stateLow & 0xFFFFFFFF) < ($il & 0xFFFFFFFF)) ? 1 : 0;
        $this->stateHigh = ($this->stateHigh + $ih + $carry) & 0xFFFFFFFF;
    }

    /**
     * Multiply two 32-bit unsigned integers and return the low 32 bits.
     */
    private function mulLo32(int $a, int $b): int
    {
        return ($a * $b) & 0xFFFFFFFF;
    }

    /**
     * Multiply two 32-bit unsigned integers and return the high 32 bits.
     */
    private function mulHi32(int $a, int $b): int
    {
        $result = $a * $b;
        // For platform independence, extract high bits via bit shift
        // On 64-bit systems this is straightforward; on 32-bit systems PHP handles it
        if (PHP_INT_MAX > 0x7FFFFFFF) {
            // 64-bit system
            return intval($result >> 32) & 0xFFFFFFFF;
        } else {
            // 32-bit system: use floating point as fallback
            return intval(($result / 4294967296.0)) & 0xFFFFFFFF;
        }
    }

    /**
     * Generate the next pseudorandom 32-bit unsigned integer.
     *
     * Applies the PCG32 output function:
     *   1. xorshift middle bits
     *   2. extract rotation amount
     *   3. rotate to produce output
     *
     * @return int Pseudorandom unsigned 32-bit value (as PHP int)
     */
    private function nextUint32(): int
    {
        $this->advance();

        // Apply output permutation
        // xorshifted = ((state >> 18) ^ state) >> 27
        $xs = ((($this->stateHigh << 14) | ($this->stateLow >> 18)) ^ $this->stateHigh) >> 27;
        $xs = $xs & 0xFFFFFFFF;

        // rot = state >> 59 (rotation amount from high 3 bits of high 32)
        $rot = ($this->stateHigh >> 27) & 0x1F;

        // Rotate: (xorshifted >> rot) | (xorshifted << (32 - rot))
        $result = (($xs >> $rot) | ($xs << (32 - $rot))) & 0xFFFFFFFF;

        return $result;
    }

    /**
     * Generate a pseudorandom integer in the range [min, max] (inclusive).
     *
     * Uses a rejection sampling approach to avoid modulo bias with non-power-of-2
     * ranges (though for benchmark purposes, bias is minimal).
     *
     * @param int $min Minimum value (inclusive)
     * @param int $max Maximum value (inclusive)
     * @return int Pseudorandom integer in [min, max]
     * @throws \InvalidArgumentException If min > max
     */
    public function nextInt(int $min, int $max): int
    {
        if ($min > $max) {
            throw new \InvalidArgumentException(
                "min ({$min}) must not be greater than max ({$max})"
            );
        }

        if ($min === $max) {
            return $min;
        }

        $range = $max - $min + 1;

        // Simple modulo approach (acceptable for benchmarking)
        // For cryptographic use, rejection sampling would be preferred
        $value = $this->nextUint32();

        // Ensure positive result on 32-bit systems
        if ($value < 0) {
            $value = $value & 0x7FFFFFFF;  // Clear sign bit
        }

        return $min + ($value % $range);
    }

    /**
     * Generate a pseudorandom floating-point number in the range [min, max).
     *
     * @param float $min Minimum value (inclusive)
     * @param float $max Maximum value (exclusive)
     * @return float Pseudorandom float in [min, max)
     * @throws \InvalidArgumentException If min >= max
     */
    public function nextFloat(float $min, float $max): float
    {
        if ($min >= $max) {
            throw new \InvalidArgumentException(
                "min ({$min}) must be strictly less than max ({$max})"
            );
        }

        // Generate uniform float in [0.0, 1.0)
        // by dividing a 32-bit uint by 2^32
        $uint = $this->nextUint32() & 0x7FFFFFFF;  // Keep positive
        $uniform = $uint / 2147483648.0;  // 2^31

        return $min + ($uniform * ($max - $min));
    }

    /**
     * Generate a pseudorandom string of given length.
     *
     * Characters are drawn from alphanumeric set: [a-zA-Z0-9].
     *
     * @param int $length Number of characters to generate
     * @return string Pseudorandom alphanumeric string
     * @throws \InvalidArgumentException If length < 0
     */
    public function nextString(int $length): string
    {
        if ($length < 0) {
            throw new \InvalidArgumentException("length must be non-negative");
        }

        if ($length === 0) {
            return '';
        }

        $charset = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
        $charsetLen = strlen($charset);
        $result = '';

        for ($i = 0; $i < $length; $i++) {
            $index = $this->nextInt(0, $charsetLen - 1);
            $result .= $charset[$index];
        }

        return $result;
    }

    /**
     * Choose a random element from an array using pseudorandom selection.
     *
     * @template T
     * @param array<T> $options Array of values to choose from
     * @return T A randomly chosen element
     * @throws \InvalidArgumentException If options array is empty
     */
    public function nextChoice(array $options): mixed
    {
        if (empty($options)) {
            throw new \InvalidArgumentException("options array must not be empty");
        }

        $index = $this->nextInt(0, count($options) - 1);
        return $options[$index];
    }
}
}

// Source: src/Dataset/Schema.php
namespace DBench86\Dataset{

/**
 * Logical schema definition for the DBench86 benchmark dataset.
 *
 * This class defines the abstract structure of all benchmark tables, independent
 * of SQL dialect. Each driver (MariaDB, PostgreSQL, SQLite) translates this model
 * into its own SQL and data type choices.
 *
 * Tables are designed to exercise realistic query patterns:
 * - Primary key lookups (users.id, products.id, etc.)
 * - Secondary index lookups (users.email, products.sku)
 * - Range queries (orders.created_at BETWEEN ...)
 * - Foreign key joins (orders → users, order_items → orders/products)
 * - Aggregations (COUNT, SUM on order_items)
 */
final class Schema
{
    /**
     * Schema version: increment whenever structural changes occur that would
     * affect data generation semantics for the same seed value.
     *
     * This ensures reproducibility across DBench86 versions and enables
     * backward compatibility checks.
     */
    public const int SCHEMA_VERSION = 1;

    /**
     * Logical definition of the 'users' table.
     *
     * Columns:
     *   id:         Numeric identifier, primary key
     *   email:      Text, unique index (for secondary key lookup)
     *   name:       Text
     *   created_at: Timestamp, indexed (for range queries)
     *
     * Workloads exercised:
     *   - Lookup by primary key (id)
     *   - Lookup by unique secondary key (email)
     *   - Range query (created_at BETWEEN t1 AND t2)
     *   - Join source (orders.user_id → users.id)
     *
     * Bound parameters per INSERT row (C): 4
     *   INSERT INTO users (email, name, created_at, ...) VALUES (?, ?, ?, ...)
     */
    public const string TABLE_USERS = 'users';
    public const array COLUMNS_USERS = [
        'id',
        'email',
        'name',
        'created_at',
    ];
    public const int BOUND_PARAMETERS_USERS = 4;

    /**
     * Logical definition of the 'products' table.
     *
     * Columns:
     *   id:    Numeric identifier, primary key
     *   sku:   Text, unique index (for secondary key lookup)
     *   name:  Text
     *   price: Numeric (decimal/float), used in aggregations
     *
     * Workloads exercised:
     *   - Lookup by primary key (id)
     *   - Lookup by unique secondary key (sku)
     *   - Join source (order_items.product_id → products.id)
     *   - Aggregation (SUM(quantity * unit_price))
     *
     * Bound parameters per INSERT row (C): 4
     *   INSERT INTO products (sku, name, price, ...) VALUES (?, ?, ?, ...)
     */
    public const string TABLE_PRODUCTS = 'products';
    public const array COLUMNS_PRODUCTS = [
        'id',
        'sku',
        'name',
        'price',
    ];
    public const int BOUND_PARAMETERS_PRODUCTS = 4;

    /**
     * Logical definition of the 'orders' table.
     *
     * Columns:
     *   id:         Numeric identifier, primary key
     *   user_id:    Foreign key to users.id, indexed (for range lookups, joins)
     *   status:     Short text (pending/completed/cancelled), for filtering
     *   created_at: Timestamp, indexed (for range queries)
     *
     * Workloads exercised:
     *   - Lookup by primary key (id)
     *   - Lookup by foreign key (user_id)
     *   - Range query (created_at BETWEEN t1 AND t2)
     *   - Join source (order_items.order_id → orders.id)
     *   - Join target (orders.user_id → users.id)
     *   - Filtering by status
     *
     * Bound parameters per INSERT row (C): 4
     *   INSERT INTO orders (user_id, status, created_at, ...) VALUES (?, ?, ?, ...)
     */
    public const string TABLE_ORDERS = 'orders';
    public const array COLUMNS_ORDERS = [
        'id',
        'user_id',
        'status',
        'created_at',
    ];
    public const int BOUND_PARAMETERS_ORDERS = 4;

    /**
     * Logical definition of the 'order_items' table.
     *
     * Columns:
     *   id:          Numeric identifier, primary key
     *   order_id:    Foreign key to orders.id, indexed (for lookups, joins)
     *   product_id:  Foreign key to products.id, indexed (for joins)
     *   quantity:    Integer, used in aggregations
     *   unit_price:  Numeric, used in aggregations
     *
     * Workloads exercised:
     *   - Lookup by primary key (id)
     *   - Lookup by foreign key (order_id, product_id)
     *   - Join with orders (order_items.order_id → orders.id)
     *   - Join with products (order_items.product_id → products.id)
     *   - Aggregation (SUM(quantity), SUM(quantity * unit_price))
     *
     * Bound parameters per INSERT row (C): 5
     *   INSERT INTO order_items (order_id, product_id, quantity, unit_price, ...)
     *   VALUES (?, ?, ?, ?, ...)
     *
     * Note: order_items has more bound parameters per row than users/products/orders.
     * This means BatchLimitCalculator will calculate a more restrictive batch size
     * for this table (fewer rows per batch) if the driver's parameter limit is reached.
     */
    public const string TABLE_ORDER_ITEMS = 'order_items';
    public const array COLUMNS_ORDER_ITEMS = [
        'id',
        'order_id',
        'product_id',
        'quantity',
        'unit_price',
    ];
    public const int BOUND_PARAMETERS_ORDER_ITEMS = 5;

    /**
     * Get all table definitions in insertion order (respecting foreign key dependencies).
     *
     * Order is critical: tables must be created (and data inserted) in dependency order.
     * - users (no dependencies)
     * - products (no dependencies)
     * - orders (depends on users)
     * - order_items (depends on orders and products)
     *
     * @return array<array{name: string, columns: array<string>, boundParameters: int}>
     */
    public static function getTables(): array
    {
        return [
            [
                'name' => self::TABLE_USERS,
                'columns' => self::COLUMNS_USERS,
                'boundParameters' => self::BOUND_PARAMETERS_USERS,
            ],
            [
                'name' => self::TABLE_PRODUCTS,
                'columns' => self::COLUMNS_PRODUCTS,
                'boundParameters' => self::BOUND_PARAMETERS_PRODUCTS,
            ],
            [
                'name' => self::TABLE_ORDERS,
                'columns' => self::COLUMNS_ORDERS,
                'boundParameters' => self::BOUND_PARAMETERS_ORDERS,
            ],
            [
                'name' => self::TABLE_ORDER_ITEMS,
                'columns' => self::COLUMNS_ORDER_ITEMS,
                'boundParameters' => self::BOUND_PARAMETERS_ORDER_ITEMS,
            ],
        ];
    }

    /**
     * Get the list of foreign key relationships in the schema.
     *
     * Each relationship is represented as:
     *   [source_table, source_column] → [target_table, target_column]
     *
     * @return array<array{source: string, sourceColumn: string, target: string, targetColumn: string}>
     */
    public static function getForeignKeys(): array
    {
        return [
            [
                'source' => self::TABLE_ORDERS,
                'sourceColumn' => 'user_id',
                'target' => self::TABLE_USERS,
                'targetColumn' => 'id',
            ],
            [
                'source' => self::TABLE_ORDER_ITEMS,
                'sourceColumn' => 'order_id',
                'target' => self::TABLE_ORDERS,
                'targetColumn' => 'id',
            ],
            [
                'source' => self::TABLE_ORDER_ITEMS,
                'sourceColumn' => 'product_id',
                'target' => self::TABLE_PRODUCTS,
                'targetColumn' => 'id',
            ],
        ];
    }

    /**
     * Get the list of indexed columns (beyond primary keys).
     *
     * These represent columns on which secondary lookups, range queries, or
     * foreign key joins are performed.
     *
     * @return array<array{table: string, column: string, unique: bool}>
     */
    public static function getIndexes(): array
    {
        return [
            // users table
            ['table' => self::TABLE_USERS, 'column' => 'email', 'unique' => true],
            ['table' => self::TABLE_USERS, 'column' => 'created_at', 'unique' => false],

            // products table
            ['table' => self::TABLE_PRODUCTS, 'column' => 'sku', 'unique' => true],

            // orders table
            ['table' => self::TABLE_ORDERS, 'column' => 'user_id', 'unique' => false],
            ['table' => self::TABLE_ORDERS, 'column' => 'created_at', 'unique' => false],

            // order_items table
            ['table' => self::TABLE_ORDER_ITEMS, 'column' => 'order_id', 'unique' => false],
            ['table' => self::TABLE_ORDER_ITEMS, 'column' => 'product_id', 'unique' => false],
        ];
    }

    /**
     * Validate schema integrity.
     *
     * Checks:
     * 1. Every table has a defined structure (columns + bound parameters)
     * 2. Every foreign key references an existing table and column
     * 3. Every indexed column exists in its table
     * 4. All bound parameter counts are positive integers
     *
     * @throws \InvalidArgumentException If validation fails
     */
    public static function validate(): void
    {
        $tableNames = array_map(fn(array $t) => $t['name'], self::getTables());
        $tablesByName = array_combine($tableNames, self::getTables());

        // Check foreign keys
        foreach (self::getForeignKeys() as $fk) {
            $source = $fk['source'];
            $target = $fk['target'];

            if (!isset($tablesByName[$source])) {
                throw new \InvalidArgumentException(
                    "Foreign key source table '{$source}' does not exist"
                );
            }

            if (!isset($tablesByName[$target])) {
                throw new \InvalidArgumentException(
                    "Foreign key target table '{$target}' does not exist"
                );
            }

            // Check source column exists
            if (!in_array($fk['sourceColumn'], $tablesByName[$source]['columns'], true)) {
                throw new \InvalidArgumentException(
                    "Foreign key source column '{$source}.{$fk['sourceColumn']}' does not exist"
                );
            }

            // Check target column exists
            if (!in_array($fk['targetColumn'], $tablesByName[$target]['columns'], true)) {
                throw new \InvalidArgumentException(
                    "Foreign key target column '{$target}.{$fk['targetColumn']}' does not exist"
                );
            }
        }

        // Check indexes
        foreach (self::getIndexes() as $index) {
            $table = $index['table'];

            if (!isset($tablesByName[$table])) {
                throw new \InvalidArgumentException(
                    "Index table '{$table}' does not exist"
                );
            }

            if (!in_array($index['column'], $tablesByName[$table]['columns'], true)) {
                throw new \InvalidArgumentException(
                    "Indexed column '{$table}.{$index['column']}' does not exist"
                );
            }
        }

        // Check bound parameters are positive
        foreach (self::getTables() as $table) {
            if ($table['boundParameters'] <= 0) {
                throw new \InvalidArgumentException(
                    "Table '{$table['name']}' has invalid bound parameter count: {$table['boundParameters']}"
                );
            }
        }
    }
}
}

// Source: src/Driver/DatabaseDriver.php
namespace DBench86\Driver{

use PDO;

/**
 * Contract for database driver implementations.
 *
 * Each driver (MariaDB, PostgreSQL, SQLite) must implement this interface
 * to provide consistent access to database-specific operations required
 * by the benchmarking framework.
 */
interface DatabaseDriver
{
    /**
     * Human-readable name of this driver (e.g., "MariaDB", "PostgreSQL", "SQLite").
     *
     * Implemented by concrete drivers as a readonly public property with a default value.
     */
    public string $name { get; }

    /**
     * PDO driver name used in DSN construction (e.g., "mysql", "pgsql", "sqlite").
     *
     * Implemented by concrete drivers as a readonly public property with a default value.
     */
    public string $pdoDriver { get; }

    /**
     * Establish a PDO connection to the target database.
     *
     * Connection parameters (host, port, username, password, database) are
     * provided to the constructor, not to this method.
     *
     * @return PDO An active, ready-to-use PDO instance
     * @throws \DBench86\Exception\DatabaseConnectionException If connection fails
     */
    public function connect(): PDO;

    /**
     * Drop all tables and reset the schema to a clean state.
     *
     * This is called before each benchmark run to ensure a predictable starting point.
     * The database connection already exists; this method must not create or drop the database itself.
     *
     * @param PDO $pdo An active database connection
     * @throws \DBench86\Exception\BenchmarkPreparationException If schema reset fails
     */
    public function resetSchema(PDO $pdo): void;

    /**
     * Create the benchmark schema (tables, indexes, constraints).
     *
     * This is called after resetSchema() to prepare for data loading and benchmarking.
     * The schema design is DBench86-specific and may differ slightly per driver
     * (e.g., data type choices, index strategies).
     *
     * @param PDO $pdo An active database connection
     * @throws \DBench86\Exception\BenchmarkPreparationException If schema creation fails
     */
    public function createSchema(PDO $pdo): void;

    /**
     * Discover and return the engine version string.
     *
     * Used for logging and validation. The format may vary by driver
     * (e.g., "MariaDB 10.6.4", "PostgreSQL 14.1", "3.40.0").
     *
     * @param PDO $pdo An active database connection
     * @return string Version string
     * @throws \DBench86\Exception\DatabaseConnectionException If version query fails
     */
    public function discoverEngineVersion(PDO $pdo): string;
}
}

// Source: src/Driver/AbstractDriver.php
namespace DBench86\Driver{

/**
 * Abstract base class for database drivers.
 *
 * Provides a common foundation for all driver implementations (MariaDB, PostgreSQL, SQLite).
 * Defines operational constraints and helper methods used across drivers.
 *
 * Each concrete driver extends this class and implements DatabaseDriver interface,
 * with driver-specific connection logic, schema operations, and version discovery.
 */
abstract class AbstractDriver implements DatabaseDriver
{
    /**
     * Maximum number of rows per batch during data insertion.
     *
     * IMPORTANT: This is an OPERATIONAL CONSTRAINT chosen by DBench86 for safety and
     * predictability, NOT a limit imposed by the database engine itself.
     *
     * - MariaDB supports millions of rows per statement
     * - PostgreSQL supports millions of rows per statement
     * - SQLite supports similar capacity
     *
     * This value (500) is a conservative choice to:
     * - Keep memory usage predictable
     * - Reduce statement recompilation overhead
     * - Ensure consistent timing across runs
     * - Simplify debugging and logging
     *
     * Individual drivers may override this constant with a different value
     * if DBench86-specific benchmarking needs require it. Any override must
     * include similar documentation explaining the choice.
     */
    public const int MAX_BATCH_SIZE = 500;

    /**
     * Maximum number of bound parameters per prepared statement.
     *
     * IMPORTANT: This is an OPERATIONAL CONSTRAINT chosen by DBench86 for safety and
     * predictability, NOT a limit imposed by the database engine itself.
     *
     * Reference limits (not enforced by DBench86 — only for context):
     * - MariaDB: The server accepts up to 2^16 (65536) placeholders in prepared statements.
     *   See: https://mariadb.com/kb/en/library/prepare-statement/
     * - PostgreSQL: Maximum 32,767 positional parameters ($1, $2, ..., $32767) per prepared statement.
     *   See: https://www.postgresql.org/docs/current/sql-prepare.html
     * - SQLite: SQLITE_LIMIT_VARIABLE_NUMBER (default 32766 since SQLite 3.32.0).
     *   See: https://www.sqlite.org/limits.html
     *
     * This value (10,000) is a conservative choice to:
     * - Keep PDO and driver memory usage under control
     * - Ensure reasonable statement preparation times
     * - Reduce the risk of parameter binding errors
     * - Maintain consistent performance profiles
     *
     * Individual drivers may override this constant with a different value
     * if DBench86-specific benchmarking needs require it. Any override must
     * include similar documentation explaining the choice.
     */
    public const int MAX_BOUND_PARAMETERS = 10_000;
}
}

// Source: src/Driver/MariaDbDriver.php
namespace DBench86\Driver{

use PDO;
use DBench86\Exception\DatabaseConnectionException;
use DBench86\Exception\BenchmarkPreparationException;

/**
 * MariaDB database driver implementation.
 *
 * Provides MariaDB-specific connection, schema management, and version discovery.
 * All connection parameters are provided via constructor; no defaults are hardcoded
 * to avoid surprises (e.g., silent Unix socket fallback when TCP is intended).
 */
class MariaDbDriver extends AbstractDriver
{
    /**
     * Human-readable name of this driver.
     * Never modified after construction.
     */
    public readonly string $name = 'MariaDB';

    /**
     * PDO driver name for DSN construction ("mysql").
     * Never modified after construction.
     */
    public readonly string $pdoDriver = 'mysql';

    /**
     * DBench86 operational constraint: maximum rows per batch insert.
     *
     * IMPORTANT: This is a choice made by DBench86 for this driver, NOT a limit
     * imposed by MariaDB itself. MariaDB supports millions of rows per statement.
     *
     * This value (2,000) is chosen for MariaDB to balance:
     * - Memory usage (larger batches than PostgreSQL due to MariaDB's efficiency)
     * - Consistent timing (avoids extreme variance in large batch execution)
     * - Debugging clarity
     *
     * Users and benchmarking code must not treat this as "MariaDB's limit".
     */
    #[\Override]
    const int MAX_BATCH_SIZE = 2_000;

    /**
     * DBench86 operational constraint: maximum bound parameters per statement.
     *
     * IMPORTANT: This is a choice made by DBench86 for this driver, NOT a limit
     * imposed by MariaDB itself.
     *
     * MariaDB accepts up to 2^16 (65,536) placeholders in a single prepared statement.
     * Reference: https://mariadb.com/kb/en/library/prepare-statement/
     *
     * This value (50,000) is chosen for MariaDB to:
     * - Reflect MariaDB's strong capacity for large parameter sets
     * - Remain conservative for production safety
     * - Balance memory usage in the driver and PDO layer
     *
     * Users and benchmarking code must not treat this as "MariaDB's limit".
     */
    #[\Override]
    const int MAX_BOUND_PARAMETERS = 50_000;

    /**
     * Construct a MariaDB driver instance.
     *
     * All connection parameters are required and provided explicitly here.
     * No defaults are inferred to avoid silent fallbacks (e.g., Unix socket when
     * TCP is intended).
     *
     * @param string $host Server hostname (e.g., "localhost", "127.0.0.1", "db.example.com")
     * @param int $port Server port (e.g., 3306)
     * @param string $database Database name (e.g., "benchmark")
     * @param string $username Database user (e.g., "root")
     * @param string $password User password (empty string is valid)
     * @param ?string $socket Unix socket path (e.g., "/run/mysqld/mysqld.sock")
     *                        If provided, takes precedence over host/port for connection.
     *                        If null, TCP via host/port is used explicitly.
     */
    public function __construct(
        private readonly string $host,
        private readonly int $port,
        private readonly string $database,
        private readonly string $username,
        private readonly string $password,
        private readonly ?string $socket = null,
    ) {}

    /**
     * Establish a PDO connection to MariaDB.
     *
     * Connection method:
     * - If $socket is provided, uses Unix socket connection
     * - Otherwise, uses explicit TCP via host:port (never relies on PDO's "localhost" heuristic)
     *
     * Error handling is set to throw exceptions immediately.
     *
     * @return PDO Active MariaDB connection
     * @throws DatabaseConnectionException If connection fails
     */
    public function connect(): PDO
    {
        try {
            // Determine DSN based on connection method
            if ($this->socket !== null) {
                // Unix socket connection
                $dsn = sprintf(
                    'mysql:unix_socket=%s;dbname=%s;charset=utf8mb4',
                    $this->socket,
                    $this->database
                );
            } else {
                // Explicit TCP connection (host:port)
                // This avoids PDO's implicit Unix socket fallback when host="localhost"
                $dsn = sprintf(
                    'mysql:host=%s;port=%d;dbname=%s;charset=utf8mb4',
                    $this->host,
                    $this->port,
                    $this->database
                );
            }

            $pdo = new PDO(
                $dsn,
                $this->username,
                $this->password,
                [
                    PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,
                ]
            );

            return $pdo;
        } catch (\PDOException $e) {
            throw new DatabaseConnectionException(
                sprintf(
                    'Failed to connect to MariaDB at %s: %s',
                    $this->socket ?? sprintf('%s:%d', $this->host, $this->port),
                    $e->getMessage()
                ),
                0,
                $e
            );
        }
    }

    /**
     * Reset the database schema by truncating all tables.
     *
     * Strategy: Uses TRUNCATE (fast, resets AUTO_INCREMENT counters) rather than
     * DROP TABLE, preserving the schema structure for performance.
     *
     * Flow:
     * 1. Disable foreign key constraint checking (SET FOREIGN_KEY_CHECKS = 0)
     * 2. Query INFORMATION_SCHEMA for all base tables in the database
     * 3. TRUNCATE each table (fast, resets auto_increment to 1)
     * 4. Re-enable foreign key checks
     *
     * Why TRUNCATE? MariaDB's TRUNCATE is faster than DELETE for large tables
     * and automatically resets AUTO_INCREMENT to 1, making it ideal for benchmark
     * resets. DROP TABLE would require re-creating the schema via createSchema().
     *
     * @param PDO $pdo Active database connection
     * @throws BenchmarkPreparationException If schema reset fails
     */
    public function resetSchema(PDO $pdo): void
    {
        try {
            // Disable foreign key checks to allow TRUNCATE of tables with FK relationships
            $pdo->exec('SET FOREIGN_KEY_CHECKS = 0');

            // Query INFORMATION_SCHEMA to get all tables in the current database
            $stmt = $pdo->query(
                'SELECT TABLE_NAME FROM INFORMATION_SCHEMA.TABLES '
                . 'WHERE TABLE_SCHEMA = DATABASE() AND TABLE_TYPE = "BASE TABLE"'
            );
            $tables = $stmt->fetchAll(PDO::FETCH_COLUMN);

            // TRUNCATE each table (fast, resets auto_increment)
            foreach ($tables as $table) {
                $pdo->exec(sprintf('TRUNCATE TABLE `%s`', addcslashes($table, '`')));
            }

            // Re-enable foreign key checks
            $pdo->exec('SET FOREIGN_KEY_CHECKS = 1');
        } catch (\PDOException $e) {
            throw new BenchmarkPreparationException(
                'Failed to reset MariaDB schema: ' . $e->getMessage(),
                0,
                $e
            );
        }
    }

    /**
     * Create the complete benchmark schema (tables, indexes, constraints).
     *
     * Translates the logical Schema model (src/Dataset/Schema.php) into MariaDB SQL:
     * - Auto-increment columns use AUTO_INCREMENT with PRIMARY KEY
     * - Numeric columns use BIGINT (IDs, quantities) or DECIMAL (prices, money)
     * - Text columns use VARCHAR or TEXT as appropriate
     * - Timestamps use DATETIME with default CURRENT_TIMESTAMP
     * - Foreign keys are defined inline with ON DELETE RESTRICT (preserves integrity)
     * - Indexes are created separately (unique constraints use UNIQUE KEY)
     *
     * Table creation order respects foreign key dependencies:
     * 1. users (no dependencies)
     * 2. products (no dependencies)
     * 3. orders (depends on users via FK)
     * 4. order_items (depends on orders and products via FKs)
     *
     * @param PDO $pdo Active database connection
     * @throws BenchmarkPreparationException If schema creation fails
     */
    public function createSchema(PDO $pdo): void
    {
        try {
            // Disable foreign key checks during creation (all tables will exist before data)
            $pdo->exec('SET FOREIGN_KEY_CHECKS = 0');

            // Create users table
            $pdo->exec(<<<'SQL'
                CREATE TABLE IF NOT EXISTS `users` (
                    `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
                    `email` VARCHAR(255) NOT NULL,
                    `name` VARCHAR(255) NOT NULL,
                    `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
                    UNIQUE KEY `idx_users_email` (`email`),
                    KEY `idx_users_created_at` (`created_at`)
                ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
            SQL);

            // Create products table
            $pdo->exec(<<<'SQL'
                CREATE TABLE IF NOT EXISTS `products` (
                    `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
                    `sku` VARCHAR(255) NOT NULL,
                    `name` VARCHAR(255) NOT NULL,
                    `price` DECIMAL(10, 2) NOT NULL,
                    UNIQUE KEY `idx_products_sku` (`sku`)
                ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
            SQL);

            // Create orders table (depends on users)
            $pdo->exec(<<<'SQL'
                CREATE TABLE IF NOT EXISTS `orders` (
                    `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
                    `user_id` BIGINT NOT NULL,
                    `status` VARCHAR(50) NOT NULL,
                    `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
                    KEY `idx_orders_user_id` (`user_id`),
                    KEY `idx_orders_created_at` (`created_at`),
                    CONSTRAINT `fk_orders_user_id` FOREIGN KEY (`user_id`)
                        REFERENCES `users` (`id`) ON DELETE RESTRICT
                ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
            SQL);

            // Create order_items table (depends on orders and products)
            $pdo->exec(<<<'SQL'
                CREATE TABLE IF NOT EXISTS `order_items` (
                    `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
                    `order_id` BIGINT NOT NULL,
                    `product_id` BIGINT NOT NULL,
                    `quantity` INT NOT NULL,
                    `unit_price` DECIMAL(10, 2) NOT NULL,
                    KEY `idx_order_items_order_id` (`order_id`),
                    KEY `idx_order_items_product_id` (`product_id`),
                    CONSTRAINT `fk_order_items_order_id` FOREIGN KEY (`order_id`)
                        REFERENCES `orders` (`id`) ON DELETE RESTRICT,
                    CONSTRAINT `fk_order_items_product_id` FOREIGN KEY (`product_id`)
                        REFERENCES `products` (`id`) ON DELETE RESTRICT
                ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
            SQL);

            // Re-enable foreign key checks
            $pdo->exec('SET FOREIGN_KEY_CHECKS = 1');
        } catch (\PDOException $e) {
            throw new BenchmarkPreparationException(
                'Failed to create MariaDB schema: ' . $e->getMessage(),
                0,
                $e
            );
        }
    }

    /**
     * Discover the MariaDB engine version.
     *
     * Executes SELECT VERSION() and returns the raw version string from the server.
     * This is the authoritative version as reported by the engine itself, not a
     * version derived from the PDO client library.
     *
     * Example returns:
     * - "10.6.4-MariaDB"
     * - "10.5.10-MariaDB"
     * - "8.0.26-0ubuntu0.20.04.1"
     *
     * @param PDO $pdo Active database connection
     * @return string Version string from SELECT VERSION()
     * @throws DatabaseConnectionException If version query fails
     */
    public function discoverEngineVersion(PDO $pdo): string
    {
        try {
            $version = $pdo->query('SELECT VERSION()')->fetchColumn();
            if ($version === false || $version === null) {
                throw new DatabaseConnectionException(
                    'MariaDB SELECT VERSION() returned no result'
                );
            }
            return (string)$version;
        } catch (\PDOException $e) {
            throw new DatabaseConnectionException(
                'Failed to discover MariaDB version: ' . $e->getMessage(),
                0,
                $e
            );
        }
    }

    /**
     * Get the human-readable name of this driver.
     *
     * @return string "MariaDB"
     */
    public function getName(): string
    {
        return $this->name;
    }

    /**
     * Get the PDO driver name for DSN construction.
     *
     * @return string "mysql"
     */
    public function getPdoDriver(): string
    {
        return $this->pdoDriver;
    }
}
}

