// Source: src/Statistics/Statistics.php
namespace DBench86\Statistics{

use InvalidArgumentException;

/**
 * Statistics calculator for benchmark measurements.
 *
 * All methods operate on arrays of numeric values (durations in nanoseconds,
 * converted to milliseconds, etc.) and return float results.
 *
 * Empty arrays are explicitly rejected with InvalidArgumentException rather
 * than silently returning NAN or 0.
 */
final class Statistics
{
    /**
     * Calculates the minimum value from an array of durations.
     *
     * @param array<int|float> $durations
     * @return float The minimum value
     * @throws InvalidArgumentException If the array is empty
     */
    public static function minimum(array $durations): float
    {
        if (count($durations) === 0) {
            throw new InvalidArgumentException('Cannot calculate minimum of empty array');
        }

        return (float) min($durations);
    }

    /**
     * Calculates the maximum value from an array of durations.
     *
     * @param array<int|float> $durations
     * @return float The maximum value
     * @throws InvalidArgumentException If the array is empty
     */
    public static function maximum(array $durations): float
    {
        if (count($durations) === 0) {
            throw new InvalidArgumentException('Cannot calculate maximum of empty array');
        }

        return (float) max($durations);
    }

    /**
     * Calculates the arithmetic mean of an array of durations.
     *
     * @param array<int|float> $durations
     * @return float The mean (average)
     * @throws InvalidArgumentException If the array is empty
     */
    public static function mean(array $durations): float
    {
        if (count($durations) === 0) {
            throw new InvalidArgumentException('Cannot calculate mean of empty array');
        }

        return (float) (array_sum($durations) / count($durations));
    }

    /**
     * Calculates the median (50th percentile) of an array of durations.
     *
     * MEDIAN CALCULATION METHOD:
     * - For odd-length arrays: the middle value after sorting
     * - For even-length arrays: the average of the two middle values (interpolation)
     *
     * This is the most common definition of median in statistics and provides
     * stability across arrays with slightly different lengths.
     *
     * Example:
     *   [1, 2, 3, 4, 5] → median = 3
     *   [1, 2, 3, 4]    → median = (2 + 3) / 2 = 2.5
     *
     * @param array<int|float> $durations
     * @return float The median value
     * @throws InvalidArgumentException If the array is empty
     */
    public static function median(array $durations): float
    {
        if (count($durations) === 0) {
            throw new InvalidArgumentException('Cannot calculate median of empty array');
        }

        $sorted = $durations;
        sort($sorted);
        $count = count($sorted);

        if ($count % 2 === 1) {
            // Odd-length array: return middle element
            return (float) $sorted[intdiv($count, 2)];
        }

        // Even-length array: interpolate between two middle elements
        $midPoint1 = $sorted[($count / 2) - 1];
        $midPoint2 = $sorted[($count / 2)];

        return ($midPoint1 + $midPoint2) / 2.0;
    }

    /**
     * Calculates the 95th percentile (p95) of an array of durations.
     *
     * P95 CALCULATION METHOD: Nearest-rank method (also called "lower inclusive" method)
     * - Calculate rank = ceil(0.95 * n), where n is the number of observations
     * - Return the value at that rank in the sorted array (1-indexed, converted to 0-indexed)
     *
     * This is a simple, deterministic method suitable for performance benchmarking.
     * It always returns an actual value from the dataset (no interpolation).
     *
     * Example:
     *   10 samples: rank = ceil(0.95 * 10) = ceil(9.5) = 10 → 10th element (index 9)
     *   100 samples: rank = ceil(0.95 * 100) = ceil(95) = 95 → 95th element (index 94)
     *   7 samples: rank = ceil(0.95 * 7) = ceil(6.65) = 7 → 7th element (index 6)
     *
     * @param array<int|float> $durations
     * @return float The 95th percentile value
     * @throws InvalidArgumentException If the array is empty
     */
    public static function p95(array $durations): float
    {
        if (count($durations) === 0) {
            throw new InvalidArgumentException('Cannot calculate p95 of empty array');
        }

        $sorted = $durations;
        sort($sorted);
        $count = count($sorted);

        // Nearest-rank method: ceil(0.95 * n)
        $rank = (int) ceil(0.95 * $count);

        // Convert to 0-indexed array offset (rank 1 → index 0)
        $index = $rank - 1;

        return (float) $sorted[$index];
    }

    /**
     * Calculates the standard deviation of an array of durations.
     *
     * STANDARD DEVIATION METHOD: Sample standard deviation (using n-1 divisor)
     * - Formula: sqrt(sum((x - mean)²) / (n - 1))
     * - Uses Bessel's correction (dividing by n-1 instead of n)
     *
     * This is the appropriate choice for benchmark measurements because:
     * 1. We typically measure a sample of execution times, not the entire population
     * 2. Sample SD (with n-1) provides an unbiased estimator of population variance
     * 3. It's the default in most statistical tools and benchmarking frameworks
     *
     * Special case: Single observation (n=1) returns 0.0, since there is no variance
     * to estimate from a single data point (denominator would be 0, returning infinity
     * would be undefined; 0 is a more practical choice for benchmarking).
     *
     * @param array<int|float> $durations
     * @return float The sample standard deviation
     * @throws InvalidArgumentException If the array is empty
     */
    public static function standardDeviation(array $durations): float
    {
        if (count($durations) === 0) {
            throw new InvalidArgumentException('Cannot calculate standard deviation of empty array');
        }

        $count = count($durations);

        // Single observation: no variance to estimate
        if ($count === 1) {
            return 0.0;
        }

        $mean = self::mean($durations);

        // Calculate sum of squared deviations
        $sumSquaredDeviations = 0.0;
        foreach ($durations as $value) {
            $deviation = $value - $mean;
            $sumSquaredDeviations += $deviation * $deviation;
        }

        // Sample variance (using n-1)
        $sampleVariance = $sumSquaredDeviations / ($count - 1);

        return sqrt($sampleVariance);
    }
}
}

// Source: src/Workload/Workload.php
namespace DBench86\Workload{

use PDO;

/**
 * Contract for a benchmark workload.
 *
 * A Workload defines a repeatable sequence of database operations that tests
 * a specific access pattern or query type. Workloads must not:
 *
 * - Format or output any report/results (that's the runner's job)
 * - Contain or manage database connection credentials (passed explicitly)
 * - Modify global benchmark configuration silently (all parameters explicit)
 * Workloads may retain prepared inputs, execution counters and restoration data
 * across execute() calls. Cleanup restores logical dataset changes after the cycle.
 *
 * Workloads are prepared once before execution, then executed repeatedly with
 * consistent parameters, then cleaned up once after all runs.
 */
interface Workload
{
    /**
     * Human-readable name of this workload.
     *
     * Used for logging and result reporting. Must be a short identifier
     * (e.g., "lookup_by_pk", "range_scan", "bulk_insert").
     *
     * @return string
     */
    public function name(): string;

    /**
     * Prepare the workload for execution.
     *
     * Called once before any execute() invocations. May create temporary tables,
     * load reference data, or prepare statements. Runs outside measured timing.
     * The caller does not guarantee an active transaction; workloads manage
     * any transactions they require.
     *
     * @param PDO $pdo Active database connection
     * @return void
     * @throws \Exception If preparation fails
     */
    public function prepare(PDO $pdo): void;

    /**
     * Execute one run of this workload.
     *
     * Performs all database operations that constitute a single benchmark run.
     * Called repeatedly (potentially hundreds of thousands of times) with the same
     * PDO connection and parameters.
     *
     * Must return the total number of **logical operations** performed, not SQL
     * statement count. For example, a bulk insert of 1000 rows returns 1000, not
     * the number of prepared statements. This count is used to calculate throughput.
     *
     * @param PDO $pdo Active database connection
     * @return int Number of logical operations completed
     * @throws \Exception If execution fails
     */
    public function execute(PDO $pdo): int;

    /**
     * Clean up after workload execution.
     *
     * Called once after all execute() invocations complete. May drop temporary
     * tables, restore modified records, or release resources. Restoration failures
     * must propagate so the caller records a cleanup error and unsuccessful benchmark.
     *
     * @param PDO $pdo Active database connection
     * @return void
     */
    public function cleanup(PDO $pdo): void;

    /**
     * Number of bound parameters required per logical row in this workload.
     *
     * Used by BatchLimitCalculator to determine maximum safe batch size.
     * Return null if not applicable (e.g., SELECT-only workloads that don't use
     * parameter binding in ways that scale with row count).
     *
     * For example:
     * - INSERT into 5 columns: return 5
     * - INSERT into 5 columns, 1000 rows per batch: return 5 (parameters per row, not per batch)
     * - SELECT with single WHERE param: return 1
     * - SELECT with no parameters: return null
     *
     * @return int|null
     */
    public function boundParametersPerRow(): ?int;
}
}

// Source: src/Workload/AggregationWorkload.php
namespace DBench86\Workload{

use PDO;

final class AggregationWorkload implements Workload
{
    private \PDOStatement|null $statement = null;
    private int $executionCount = 0;

    public function name(): string
    {
        return 'aggregation';
    }

    public function prepare(PDO $pdo): void
    {
        // Verify that there are orders to aggregate
        $result = $pdo->query('SELECT COUNT(*) FROM orders');
        $count = $result->fetchColumn();

        if ($count === 0 || $count === false) {
            throw new \RuntimeException('No orders found in database for AggregationWorkload');
        }

        // Aggregation query: count items and sum quantities per order status
        // This tests GROUP BY, COUNT, and SUM aggregates
        $this->statement = $pdo->prepare(
            'SELECT o.status,
                    COUNT(DISTINCT o.id) as order_count,
                    COUNT(DISTINCT oi.id) as item_count,
                    SUM(COALESCE(oi.quantity, 0)) as total_quantity,
                    AVG(COALESCE(oi.unit_price, 0)) as avg_price
             FROM orders o
             LEFT JOIN order_items oi ON o.id = oi.order_id
             WHERE o.status IN (?, ?)
             GROUP BY o.status'
        );
        $this->executionCount = 0;
    }

    public function execute(PDO $pdo): int
    {
        if ($this->statement === null) {
            throw new \RuntimeException('Workload not prepared');
        }

        // Cycle through different status combinations on each execution
        $statuses = ['pending', 'completed', 'cancelled'];
        $status1 = $statuses[$this->executionCount % count($statuses)];
        $status2 = $statuses[($this->executionCount + 1) % count($statuses)];
        $this->executionCount++;

        $this->statement->execute([$status1, $status2]);
        $rows = $this->statement->fetchAll(\PDO::FETCH_ASSOC);
        $rowCount = count($rows);


        return $rowCount;
    }

    public function cleanup(PDO $pdo): void
    {
    }

    public function boundParametersPerRow(): ?int
    {
        return null;
    }
}
}

// Source: src/Workload/BatchInsertWorkload.php
namespace DBench86\Workload{

use DBench86\Benchmark\BatchLimitCalculator;
use DBench86\Dataset\DeterministicGenerator;
use DBench86\Driver\DatabaseDriver;
use PDO;

final class BatchInsertWorkload implements Workload
{
    private \PDOStatement|null $statement = null;
    private DeterministicGenerator|null $generator = null;
    private int $executionCount = 0;
    private int $effectiveBatchSize = 100;
    private int $parametersPerRow = 3;
    private int $requestedBatchSize = 100;
    private readonly ?DatabaseDriver $driver;

    /**
     * @param DatabaseDriver|null $driver Database driver for calculating batch limits.
     *        If null, this instance can only be used to retrieve its name() for listing.
     *        Calling prepare() or execute() without a driver will raise an exception.
     * @param int $requestedBatchSize Desired batch size (will be clamped to driver limits)
     */
    public function __construct(?DatabaseDriver $driver = null, int $requestedBatchSize = 100)
    {
        $this->requestedBatchSize = $requestedBatchSize;
        $this->driver = $driver;
    }

    public function name(): string
    {
        return 'batch_insert';
    }

    public function prepare(PDO $pdo): void
    {
        if ($this->driver === null) {
            throw new \RuntimeException(
                'BatchInsertWorkload requires a DatabaseDriver to execute. '
                . 'This workload was instantiated in listing mode (driver=null). '
                . 'Use getAllWorkloads($driver) to get executable workloads.'
            );
        }

        $this->generator = new DeterministicGenerator(88888);
        $this->executionCount = 0;

        // For INSERT INTO products (sku, name, price): exactly 3 parameters per row
        $this->parametersPerRow = 3;

        // Calculate effective batch size using the driver instance (always available)
        $driverLimit = BatchLimitCalculator::driverLimit(
            $this->driver,
            $this->parametersPerRow
        );

        // Clamp requested batch size to calculated limit
        $this->effectiveBatchSize = BatchLimitCalculator::effectiveBatchSize(
            $this->requestedBatchSize,
            $driverLimit
        );

        // Prepare placeholder for batch insert
        $placeholders = implode(', ', array_fill(0, $this->effectiveBatchSize, '(?, ?, ?)'));

        $sql = 'INSERT INTO products (sku, name, price) VALUES ' . $placeholders;
        $this->statement = $pdo->prepare($sql);
    }

    public function execute(PDO $pdo): int
    {
        if ($this->statement === null || $this->generator === null) {
            throw new \RuntimeException('Workload not prepared');
        }

        $params = [];
        for ($i = 0; $i < $this->effectiveBatchSize; $i++) {
            $params[] = $this->generator->nextString(16);
            $params[] = $this->generator->nextString(50);
            $params[] = round($this->generator->nextFloat(1.0, 999.99), 2);
        }

        $this->statement->execute($params);
        $this->executionCount += $this->effectiveBatchSize;


        return $this->effectiveBatchSize;
    }

    public function cleanup(PDO $pdo): void
    {
        if ($this->executionCount > 0) {
            // Get the IDs of inserted products
            $lastInsertedIds = $pdo->query(
                'SELECT id FROM products ORDER BY id DESC LIMIT ' . $this->executionCount
            )->fetchAll(\PDO::FETCH_COLUMN);

            if (!empty($lastInsertedIds)) {
                $idList = implode(',', $lastInsertedIds);
                // First delete order_items that reference these products (FK constraint)
                $pdo->exec("DELETE FROM order_items WHERE product_id IN ({$idList})");
                // Then delete the products themselves
                $pdo->exec("DELETE FROM products WHERE id IN ({$idList})");
            }
        }
    }

    public function boundParametersPerRow(): ?int
    {
        return $this->parametersPerRow;
    }
}
}

// Source: src/Workload/DeleteByPrimaryKeyWorkload.php
namespace DBench86\Workload{

use DBench86\Dataset\DeterministicGenerator;
use PDO;

final class DeleteByPrimaryKeyWorkload implements Workload
{
    private \PDOStatement|null $deleteStatement = null;
    private \PDOStatement|null $insertStatement = null;
    private DeterministicGenerator|null $generator = null;
    private array $productIds = [];
    private int $currentIndex = 0;
    private array $deletedProducts = [];
    private array $productsDeletedInRun = [];
    private array $originalOrderItems = [];

    public function __construct(private readonly DeterministicSamples $samples = new DeterministicSamples()) {}

    public function name(): string
    {
        return 'delete_by_pk';
    }

    public function prepare(PDO $pdo): void
    {
        $this->generator = new DeterministicGenerator(55555);
        $this->currentIndex = 0;
        $this->productsDeletedInRun = [];
        $this->productIds = [];

        $this->productIds = $this->samples->tableIds($pdo, 'products', $this->name());
        $this->deletedProducts = [];
        $this->originalOrderItems = [];
        $items = $pdo->prepare('SELECT id, order_id, product_id, quantity, unit_price FROM order_items WHERE product_id = ?');
        $lookup = $pdo->prepare('SELECT id, sku, name, price FROM products WHERE id = ?');
        foreach ($this->productIds as $id) {
            $lookup->execute([$id]);
            $this->deletedProducts[$id] = $lookup->fetch(PDO::FETCH_ASSOC);
            $lookup->closeCursor();
            $items->execute([$id]);
            $this->originalOrderItems[$id] = [];
            while ($item = $items->fetch(PDO::FETCH_ASSOC)) {
                $this->originalOrderItems[$id][] = $item;
            }
            $items->closeCursor();
        }

        $this->deleteStatement = $pdo->prepare('DELETE FROM products WHERE id = ?');
        $this->insertStatement = $pdo->prepare(
            'INSERT INTO products (id, sku, name, price) VALUES (?, ?, ?, ?)'
        );
    }

    public function execute(PDO $pdo): int
    {
        if ($this->deleteStatement === null) {
            throw new \RuntimeException('Workload not prepared');
        }

        $productId = $this->productIds[$this->currentIndex % count($this->productIds)];
        $this->currentIndex++;

        // Track which product will be deleted
        $this->productsDeletedInRun[$productId] = true;

        // First delete order_items that reference this product to maintain FK constraint
        $pdo->prepare('DELETE FROM order_items WHERE product_id = ?')->execute([$productId]);

        // Then delete the product itself
        $this->deleteStatement->execute([$productId]);

        return 1;
    }

    public function cleanup(PDO $pdo): void
    {
        if ($this->insertStatement === null || $this->productsDeletedInRun === []) {
            return;
        }
        // Preparation snapshots only sampled products and their dependent items.
        // Existence checks also handle an execution that failed between the two deletes.
        $productExists = $pdo->prepare('SELECT id FROM products WHERE id = ?');
        $itemExists = $pdo->prepare('SELECT id FROM order_items WHERE id = ?');
        $restoreItem = $pdo->prepare(
            'INSERT INTO order_items (id, order_id, product_id, quantity, unit_price) VALUES (?, ?, ?, ?, ?)'
        );
        foreach (array_keys($this->productsDeletedInRun) as $productId) {
            $product = $this->deletedProducts[$productId];
            $productExists->execute([$productId]);
            $exists = $productExists->fetchColumn() !== false;
            $productExists->closeCursor();
            if (!$exists) {
                try {
                    $this->insertStatement->execute([
                        $product['id'], $product['sku'], $product['name'], $product['price'],
                    ]);
                } finally {
                    $this->insertStatement->closeCursor();
                }
            }
            foreach ($this->originalOrderItems[$productId] as $item) {
                $itemExists->execute([$item['id']]);
                $exists = $itemExists->fetchColumn() !== false;
                $itemExists->closeCursor();
                if (!$exists) {
                    $restoreItem->execute([
                        $item['id'], $item['order_id'], $item['product_id'],
                        $item['quantity'], $item['unit_price'],
                    ]);
                }
            }
            unset($this->productsDeletedInRun[$productId]);
        }
    }

    public function boundParametersPerRow(): ?int
    {
        return null;
    }
}
}

// Source: src/Workload/DeterministicSamples.php
namespace DBench86\Workload{

use PDO;

/** Small, stratified samples from the generated contiguous primary keys 1..N. */
final class DeterministicSamples
{
    public function __construct(
        public readonly int $executions = 35,
        public readonly int $seed = 42_000,
    ) {
        if ($executions <= 0) {
            throw new \InvalidArgumentException('Sample execution count must be positive');
        }
    }

    /** @return list<int> O(executions), never constructs range(1, rows). */
    public function ids(int $rows, string $identity): array
    {
        if ($rows <= 0) {
            throw new \RuntimeException("No rows available for {$identity}");
        }
        $count = min($rows, $this->executions);
        $ids = [];
        for ($i = 0; $i < $count; $i++) {
            $low = (int)floor($i * ($rows / $count)) + 1;
            $high = (int)floor(($i + 1) * ($rows / $count));
            $hash = hexdec(substr(hash('sha256', "{$this->seed}:{$rows}:{$identity}:{$i}"), 0, 8));
            $ids[] = $low + ($hash % ($high - $low + 1));
        }
        return $ids;
    }

    /** Verify the dataset invariant before deriving keys instead of scanning candidates. */
    public function tableIds(PDO $pdo, string $table, string $identity): array
    {
        if (!in_array($table, ['users', 'orders', 'products'], true)) {
            throw new \InvalidArgumentException('Unsupported sample table');
        }
        $bounds = $pdo->query("SELECT COUNT(*) AS n, MIN(id) AS lo, MAX(id) AS hi FROM {$table}")->fetch(PDO::FETCH_ASSOC);
        $rows = (int)$bounds['n'];
        if ($rows === 0 || (int)$bounds['lo'] !== 1 || (int)$bounds['hi'] !== $rows) {
            throw new \RuntimeException("{$identity} requires generated contiguous {$table} IDs 1..N; repopulate the dataset");
        }
        return $this->ids($rows, $identity);
    }
}
}

